{"command":"python3 - << 'PY'
import pty, os, subprocess, sys, select, time

def run_pty(args, allocate="all"):
    # allocate master/slave for stderr +/- stdin
    master_out, slave_out = pty.openpty()
    master_err, slave_err = pty.openpty()
    # also stdin pty?
    master_in, slave_in = pty.openpty()
    # set winsize
    import fcntl, termios, struct
    winsize = struct.pack("HHHH", 24, 80, 0, 0)
    for fd in [slave_out, slave_err, slave_in]:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, winsize)
    env={**os.environ,"TERM":"xterm-256color","HOME":"/tmp/fakehome","BROOT_CONFIG_DIR":"/tmp/fakehome/.config/broot","BR_INSTALL":"no"}
    if allocate=="stderr_only_pty_stdout_pipe_stdin_pty":
        p=subprocess.Popen(args, stdin=slave_in, stdout=subprocess.PIPE, stderr=slave_err, env=env)
    elif allocate=="all_pty_same":
        p=subprocess.Popen(args, stdin=slave_in, stdout=slave_in, stderr=slave_in, env=env)
    elif allocate=="stdin_pty_stdout_pipe_stderr_pipe":
        p=subprocess.Popen(args, stdin=slave_in, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    else:
        p=subprocess.Popen(args, stdin=slave_in, stdout=slave_out, stderr=slave_err, env=env)
    for fd in [slave_out, slave_err, slave_in]:
        try: os.close(fd)
        except: pass
    # read with timeout
    out_data=b""
    start=time.time()
    # For pipe case, use communicate timeout
    try:
        if allocate in ("stderr_only_pty_stdout_pipe_stdin_pty","stdin_pty_stdout_pipe_stderr_pipe"):
            out,err=p.communicate(timeout=3)
            print(" allocate",allocate,"exit",p.returncode)
            print(" stdout pipe",out)
            print(" stderr pipe",err)
            # also try read pty masters nonblocking
            for name,m in [("err_pty",master_err),("in_pty",master_in)]:
                os.set_blocking(m, False)
                try:
                    data=b""
                    while True:
                        chunk=os.read(m, 65536)
                        if not chunk: break
                        data+=chunk
                except Exception as e:
                    data=data if 'data' in locals() else b""
                    #print(name,e)
                print(name, data[:2000])
        else:
            # read masters until process ends
            data_map={master_out:b"", master_err:b"", master_in:b""}
            masters=[master_out, master_err, master_in]
            while time.time()-start<3:
                if p.poll() is not None:
                    # drain
                    time.sleep(0.2)
                    for m in masters:
                        os.set_blocking(m, False)
                        try:
                            while True:
                                chunk=os.read(m,65536)
                                if not chunk: break
                                data_map[m]+=chunk
                        except: pass
                    break
                r,_,_=select.select(masters,[],[],0.2)
                for m in r:
                    try:
                        chunk=os.read(m,65536)
                        data_map[m]+=chunk
                    except: pass
            print(" allocate",allocate,"exit",p.poll())
            for m,d in data_map.items():
                print(m, d[:2000])
            if p.poll() is None:
                p.kill()
    except subprocess.TimeoutExpired:
        p.kill()
        print("timeout",allocate)
        print(p.communicate())

for alloc in ["stderr_only_pty_stdout_pipe_stdin_pty","stdin_pty_stdout_pipe_stderr_pipe","all"]:
    print("\n====",alloc)
    run_pty(["/workspace/executable","--color","no","--height","20","-c",":pt","/tmp/demo"], allocate=alloc)
PY
"}

