import pty, os, subprocess, fcntl, termios, struct, re, time, select
def run_pty(term, cols, rows=40):
    master, slave = pty.openpty()
    winsize=struct.pack("HHHH", rows, cols, 0,0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    env={"PATH":os.environ["PATH"],"HOME":"/tmp/fakehome","BROOT_CONFIG_DIR":"/tmp/fakehome/.config/broot","BR_INSTALL":"no"}
    if term is not None:
        env["TERM"]=term
    p=subprocess.Popen(["/workspace/executable","--help"], stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=env)
    os.close(slave)
    data=b""
    while True:
        try:
            chunk=os.read(master,65536)
            if not chunk: break
            data+=chunk
        except OSError:
            break
        if p.poll() is not None:
            # drain
            pass
    p.wait()
    text=data.decode(errors='ignore')
    clean=re.sub(r'\x1b\[[0-9;]*[a-zA-Z]','',text)
    clean=re.sub(r'\x1b\][^ \x07]*\x07','',clean)
    lines=clean.splitlines()
    # strip \r
    lines=[l.rstrip('\r') for l in lines]
    if lines:
        print(f"term={term} cols={cols} maxlen={max(len(l) for l in lines)} nlines={len(lines)} first={lines[:3]}")
    else:
        print("no lines", term, cols, data[:500])
    return data

for cols in [60,80,100,120,200]:
    run_pty("xterm-256color", cols)
for term in [None,"","dumb","unknown"]:
    run_pty(term, 100)
for cols in [60,80,100]:
    run_pty(None, cols)
