import pty, os, subprocess, fcntl, termios, struct, re, time, select

def run_broot(args, stdin_size=(24,80), stdout_size=None, stderr_size=None, stdin_pty=True, stdout_pipe=True, stderr_pipe=False, env_extra={}):
    """
    Returns (exit, stdout_bytes, stderr_bytes)
    stdin via pty slave, stderr via pty unless stderr_pipe, stdout via pipe unless stdout_size.
    """
    masters={}
    slaves={}
    def make(name, size):
        m,s=pty.openpty()
        if size:
            fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack("HHHH", size[0], size[1], 0,0))
        masters[name]=m; slaves[name]=s
        return s
    kwargs={}
    if stdin_pty:
        kwargs['stdin']=make('stdin', stdin_size)
    else:
        kwargs['stdin']=subprocess.PIPE
    if stdout_size:
        kwargs['stdout']=make('stdout', stdout_size)
    else:
        kwargs['stdout']=subprocess.PIPE
    if stderr_size or not stderr_pipe:
        # default stderr pty with stdin size if not specified?
        sz = stderr_size or stdin_size
        kwargs['stderr']=make('stderr', sz)
    else:
        kwargs['stderr']=subprocess.PIPE
    env={"PATH":os.environ["PATH"],"HOME":"/tmp/fakehome","BROOT_CONFIG_DIR":"/tmp/fakehome/.config/broot","BR_INSTALL":"no","TERM":"xterm-256color"}
    env.update(env_extra)
    p=subprocess.Popen(["/workspace/executable"]+args, env=env, **kwargs)
    for s in slaves.values():
        os.close(s)
    # read ptys nonblocking until exit
    data={k:b"" for k in masters}
    # if stdout pipe, need to read via communicate? Mixing pipes/ptys is tricky: we will use select on masters and p.stdout if any
    start=time.time()
    stdout_data=b""
    stderr_data=b""
    # Set masters nonblocking
    for m in masters.values():
        os.set_blocking(m, False)
    if p.stdout:
        os.set_blocking(p.stdout.fileno(), False)
    if p.stderr:
        os.set_blocking(p.stderr.fileno(), False)
    while time.time()-start<5:
        if p.poll() is not None:
            time.sleep(0.2)
            # final drain
            for name,m in masters.items():
                try:
                    while True:
                        chunk=os.read(m,65536)
                        if not chunk: break
                        data[name]+=chunk
                except: pass
            if p.stdout:
                try:
                    while True:
                        chunk=p.stdout.read()
                        if not chunk: break
                        stdout_data+=chunk if isinstance(chunk,bytes) else chunk.encode()
                except: pass
            if p.stderr:
                try:
                    while True:
                        chunk=p.stderr.read()
                        if not chunk: break
                        stderr_data+=chunk if isinstance(chunk,bytes) else chunk.encode()
                except: pass
            break
        # poll readable
        fds=[]
        fdmap={}
        for name,m in masters.items():
            fds.append(m); fdmap[m]=('pty',name)
        if p.stdout:
            fds.append(p.stdout.fileno()); fdmap[p.stdout.fileno()]=('stdout',None)
        if p.stderr:
            fds.append(p.stderr.fileno()); fdmap[p.stderr.fileno()]=('stderr',None)
        if fds:
            r,_,_=select.select(fds,[],[],0.2)
            for fd in r:
                kind,name=fdmap[fd]
                try:
                    chunk=os.read(fd,65536)
                except: chunk=b""
                if kind=='pty':
                    data[name]+=chunk
                elif kind=='stdout':
                    stdout_data+=chunk
                else:
                    stderr_data+=chunk
        else:
            time.sleep(0.1)
    else:
        p.kill()
    # combine: stdout output is either pipe or pty 'stdout', stderr is pty 'stderr' or pipe
    if 'stdout' in data:
        stdout_data=data['stdout']
    if 'stderr' in data:
        stderr_data=data['stderr']
    return p.poll(), stdout_data, stderr_data, data.get('stdin',b"")

# test safe input sending? For interactive, need write to stdin master. Our util doesn't support yet. For -c commands, no input needed.
