import pty, os, subprocess, fcntl, termios, struct, select, time, pathlib, shutil
home="/tmp/fakehome_customskin"
def setup():
    shutil.rmtree(home,ignore_errors=True)
    base=pathlib.Path(home,".config/broot"); (base/"skins").mkdir(parents=True)
    (base/"conf.hjson").write_text("imports: [\n {\n luma: dark\n file: skins/dark.hjson\n }\n {\n luma: light\n file: skins/light.hjson\n }\n {\n luma: unknown\n file: skins/unknown.hjson\n }\n]\n")
    for n in ["dark","light","unknown"]:
        (base/f"skins/{n}.hjson").write_text("skin: { file: ansi(196) None }\n")
def run(stdout_pty, stdin_pty, stderr_pty, env_extra, answer=None):
    setup()
    masters={}
    def make(name):
        m,s=pty.openpty(); fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack("HHHH",24,80,0,0)); masters[name]=(m,s); return s
    stdin_fd=make('in') if stdin_pty else subprocess.PIPE
    stdout_fd=make('out') if stdout_pty else subprocess.PIPE
    stderr_fd=make('err') if stderr_pty else subprocess.PIPE
    env={"PATH":os.environ["PATH"],"HOME":home,"BROOT_CONFIG_DIR":home+"/.config/broot","BR_INSTALL":"no","TERM":"xterm-256color"}
    env.update(env_extra)
    # ctty only if stdin pty: set ctty from stdin
    def pre():
        os.setsid()
        if stdin_pty:
            fcntl.ioctl(0, termios.TIOCSCTTY,0)
    p=subprocess.Popen(["/workspace/executable","/tmp/demo"], stdin=stdin_fd, stdout=stdout_fd, stderr=stderr_fd, env=env, preexec_fn=pre)
    for m,s in masters.values(): os.close(s)
    data={}; start=time.time(); ans=False
    while time.time()-start<3:
        fds=[m for m,_ in masters.values()]
        if p.stdout: fds.append(p.stdout.fileno())
        if p.stderr: fds.append(p.stderr.fileno())
        if not fds: break
        r,_,_=select.select(fds,[],[],0.05)
        for fd in r:
            try: chunk=os.read(fd,65536)
            except: chunk=b""
            # collect all in one blob
            data.setdefault('all',b""); data['all']+=chunk
            if not ans and b'\x1b]11;?' in chunk and answer:
                # answer via stdin master if exists else stdout master
                am=masters.get('in',masters.get('out'))[0]
                os.write(am, f"\x1b]11;{answer}\x07\x1b[0n".encode()); ans=True
        if p.poll() is not None:
            break
    if p.poll() is None: p.kill()
    alldata=data.get('all',b"")
    print(f"outpty={stdout_pty} inpty={stdin_pty} errpty={stderr_pty} extra={env_extra} ans={answer} ->", "dark" if b'/dark.hjson' in alldata else "light" if b'/light.hjson' in alldata else "unknown" if b'/unknown.hjson' in alldata else alldata[:200])

for outp in [True,False]:
    for inp in [True,False]:
        for errp in [True,False]:
