import re, struct, fcntl, termios, tty, select, time, errno, stat, pwd, grp, math, subprocess, shlex, unicodedata, json
from pathlib import Path

# ---------------- style helpers for stdout messages (install, removing, etc) ----------------
def _no_color_active():
    v=os.environ.get("NO_COLOR")
    return v is not None and v!=""

def esc_seq(s):
    # apply NO_COLOR transformation to a raw escape sequence string if needed.
    # Colour sequences (38;5,48;5,38;2,48;2,39,49, and standard fg/bg 30-37,40-47,90-97,100-107) become \x1b[m
    # Attribute sequences (0,1,3,4,7 etc) stay.
    if not _no_color_active():
        return s
    # s is like \x1b[48;5;234m or \x1b[39m
    m=re.match(r'^\x1b\[([0-9;]*)m$', s)
    if not m:
        return s
    code=m.group(1)
    if code in ("0","1","2","3","4","5","7","8",""):
        # attribute or reset ; empty is already \x1b[m
        return s
    # if it's a single attribute inc (?)  check
    # colour codes contain 38,48,39,49 or 30-37 etc.
    return "\x1b[m"

def S(parts):
    # parts list of either raw escape code strings (starting \x1b[) or text - apply NO_COLOR to escapes
    out=[]
    for p in parts:
        if p.startswith("\x1b["):
            out.append(esc_seq(p))
        else:
            out.append(p)
    return "".join(out)

def code_fixed(text):
    # style used for paths / code in install messages: bg 234 fg250
    return S(["\x1b[48;5;234m","\x1b[38;5;250m",text,"\x1b[49m","\x1b[39m"])

def bold_text(text):
    return S(["\x1b[1m",text,"\x1b[0m"])

def purple_italic(text):
    # \x1b[38;5;13m \x1b[3m text \x1b[0m
    return S(["\x1b[38;5;13m","\x1b[3m",text,"\x1b[0m"])

def bullet():
    return S(["\x1b[38;5;240m","•","\x1b[39m"])

# write stdout text (str) - ensure flush
def out_write(s):
    sys.stdout.write(s)
    sys.stdout.flush()

def err_write(s):
    sys.stderr.write(s)
    sys.stderr.flush()

class BroootError(Exception):
    pass

def io_error_msg(e):
    # e is OSError, format as two kinds observed:
    # "IO Error : No such file or directory (os error 2)\n"  - generic from ? main returning Err(io error)
    # some custom: 'IO Error : "/path" isn\'t a directory\n'
    if isinstance(e, str):
        return f"IO Error : {e}\n"
    err_no = e.errno if getattr(e,'errno',None) is not None else 2
    msg = os.strerror(err_no) if err_no else str(e)
    return f"IO Error : {msg} (os error {err_no})\n"

# ---------------- terminal size ----------------
def _terminfo_cols_lines():
    term=os.environ.get("TERM")
    if term is None:
        return None
    # use tput if available
    try:
        cols=None; lines=None
        # tput may not exist in some env; try
        r=subprocess.run(["tput","-T",term,"cols"], capture_output=True, text=True, timeout=2)
        if r.returncode!=0:
            return None
        cols=int(r.stdout.strip())
        r=subprocess.run(["tput","-T",term,"lines"], capture_output=True, text=True, timeout=2)
        if r.returncode!=0:
            return None
        lines=int(r.stdout.strip())
        if cols<=0 or lines<=0:
            return None
        return (cols,lines)
    except Exception:
        return None

def terminal_size_stdout():
    # returns (cols, rows) or None, following term_size crate behaviour approximated
    # 1) ioctl on stdout (fd1)
    try:
        if os.isatty(1):
            packed=fcntl.ioctl(1, termios.TIOCGWINSZ, struct.pack("HHHH",0,0,0,0))
            rows,cols,_,_=struct.unpack("HHHH",packed)
            if cols>0 and rows>0:
                return (cols,rows)
            if cols>0 or rows>0:
                # avoid dangerous zero sizes: treat partial as fallback to avoid hangs
                # Reference may return (cols,rows) with zero, but we approximate fallback
                return (cols if cols>0 else 80, rows if rows>0 else 24)
            # cols==0 and rows==0 -> reference returns (0,?) leading to weird behaviour; we fallback
            # fall through to terminfo
    except Exception:
        pass
    ti=_terminfo_cols_lines()
    if ti is None:
        return None
    cols,lines=ti
    # COLUMNS / LINES env override terminfo if parse as positive int
    try:
        c=os.environ.get("COLUMNS")
        if c is not None:
            ci=int(c)
            if ci>0:
                cols=ci
    except Exception:
        pass
    try:
        l=os.environ.get("LINES")
        if l is not None:
            li=int(l)
            if li>0:
                lines=li
    except Exception:
        pass
    return (cols,lines)

def help_width():
    sz=terminal_size_stdout()
    if sz is None:
        return 50
    w=sz[0]
    if w<=0:
        return 50
    return min(w,110)

def tui_area_size(height_arg=None):
    sz=terminal_size_stdout()
    if sz is None:
        cols,rows=50,20
    else:
        cols,rows=sz
        if cols<=0:
            cols=50
        if rows<=0:
            rows=20
    if height_arg is not None:
        rows=height_arg
    return (cols,rows)

# ---------------- luma ----------------
_ANSI16_RGB=[
(0,0,0),(128,0,0),(0,128,0),(128,128,0),(0,0,128),(128,0,128),(0,128,128),(192,192,192),
(128,128,128),(255,0,0),(0,255,0),(255,255,0),(0,0,255),(255,0,255),(0,255,255),(255,255,255),
]
def ansi256_to_rgb(n):
    if n<16:
        return _ANSI16_RGB[n]
    if n>=232:
        v=8+(n-232)*10
        return (v,v,v)
    n-=16
    r=(n//36)%6; g=(n//6)%6; b=n%6
