    return (conv(r),conv(g),conv(b))

def rgb_luma(r,g,b):
    # Rec2020 coefficients divided by 256 as per observed thresholds
    return (0.2627*r+0.678*g+0.0593*b)/256.0

_query_cache={'attempted':False,'value':None}
def query_terminal_luma():
    if _query_cache['attempted']:
        return _query_cache['value']
    _query_cache['attempted']=True
    _query_cache['value']=None
    # conditions for query
    if "TERM" not in os.environ:
        return None
    if os.environ.get("TERM")=="dumb":
        return None
    try:
        if not (os.isatty(0) and os.isatty(1)):
            return None
    except Exception:
        return None
    # attempt query
    try:
        fd_in=0
        old_attr=termios.tcgetattr(fd_in)
    except Exception:
        return None
    data=b""
    try:
        # set raw
        tty.setraw(fd_in)
        # write query to stdout fd 1
        os.write(1,b"\x1b]11;?\x07\x1b[5n")
        deadline=time.time()+0.1
        # read until DSR response or deadline
        while time.time()<deadline:
            remaining=deadline-time.time()
            if remaining<=0:
                break
            r,_,_=select.select([fd_in],[],[],remaining)
            if not r:
                break
            try:
                chunk=os.read(fd_in,1024)
            except Exception:
                break
            if not chunk:
                break
            data+=chunk
            if re.search(rb'\x1b\[[0-9;]*n',data):
                break
    except Exception:
        pass
    finally:
        try:
            termios.tcsetattr(fd_in, termios.TCSADRAIN, old_attr)
        except Exception:
            pass
    if not data:
        return None
    # parse OSC 11 response
    m=re.search(rb'\x1b\]11;([^\x07\x1b]+)(?:\x07|\x1b\\)',data)
    if not m:
        return None
    try:
        inside=m.group(1).decode(errors='ignore').strip()
        # format rgb:RR/GG/BB or rgba:.. or RRGGBB etc
        rgb=None
        mm=re.match(r'rgba?:(.+)',inside)
        if mm:
            parts=mm.group(1).split('/')
            if len(parts)>=3:
                comps=[]
                for p in parts[:3]:
                    # p hex 1-4 digits
                    v=int(p,16)
                    maxv=(16**len(p))-1
                    if maxv<=0:
                        comps.append(0)
                    else:
                        comps.append(int(round(v*255/maxv)))
                rgb=tuple(comps)
        else:
            # maybe #RRGGBB or RRGGBB
            mm=re.match(r'#?([0-9a-fA-F]{6})$',inside)
            if mm:
                h=mm.group(1)
                rgb=(int(h[0:2],16),int(h[2:4],16),int(h[4:6],16))
        if rgb is None:
            return None
        val=rgb_luma(*rgb)
        _query_cache['value']=val
        return val
    except Exception:
        return None

def luma_from_colorfgbg():
    v=os.environ.get("COLORFGBG")
    if v is None:
        return None
    parts=v.split(';')
    if len(parts)<2:
        return None
    last=parts[-1]
    # Rust u8 parse: allow leading +? int() in python allows spaces - must reject if not exactly digits (+ optional leading +)
    if not re.fullmatch(r'\+?[0-9]+',last):
        return None
    try:
        n=int(last)
    except Exception:
        return None
    if n<0 or n>255:
        return None
    rgb=ansi256_to_rgb(n)
    return rgb_luma(*rgb)

def luma_for_help():
    q=query_terminal_luma()
    if q is not None:
        return q
    return luma_from_colorfgbg()

def luma_for_config():
    # only if stdout is a tty
    try:
        if not os.isatty(1):
            return None
    except Exception:
        return None
    q=query_terminal_luma()
    if q is not None:
        return q
    return luma_from_colorfgbg()

def config_luma_category():
    l=luma_for_config()
    if l is None:
        return "unknown"
    return "light" if l>0.6 else "dark"

# ---------------- shell functions ----------------
PYEOF
"}

