{"command":"cat >> broot.py << 'PYEOF'

# ---------------- styling / wrapping for help ----------------
_next_cid=1
def new_cid():
    global _next_cid; _next_cid+=1; return _next_cid

class Compound:
    __slots__=("text","style","cid")
    def __init__(self,text,style="plain",cid=None):
        self.text=text; self.style=style; self.cid=cid if cid is not None else new_cid()

class Atom:
    __slots__=("text","style","cid")
    def __init__(self,text,style,cid):
        self.text=text; self.style=style; self.cid=cid
    def vis_len(self):
        return text_width(self.text)

def text_width(s):
    w=0
    for ch in s:
        if unicodedata.combining(ch):
            continue
        ea=unicodedata.east_asian_width(ch)
        if ea in ("W","F"):
            w+=2
        else:
            w+=1
    return w

def compounds_to_atoms(compounds):
    atoms=[]
    for comp in compounds:
        if comp.text=="":
            atoms.append(Atom("",comp.style,comp.cid))
        else:
            for m in re.finditer(r'[^ ]+| ',comp.text):
                atoms.append(Atom(m.group(0),comp.style,comp.cid))
    return atoms

def wrap_atoms(atoms,width):
    if width<=0:
        width=80
    lines=[]; cur=[]; cur_len=0
    # Use an index queue because hard splitting mutates
    queue=list(atoms)
    idx=0
    while idx < len(queue):
        atom=queue[idx]
        if atom.text=="":
            cur.append(atom); idx+=1; continue
        if atom.text==" ":
            if cur_len+1<=width:
                cur.append(atom); cur_len+=1; idx+=1
            else:
                lines.append(cur); cur=[]; cur_len=0; idx+=1  # drop space
            continue
        L=atom.vis_len()
        if cur_len+L<=width:
            cur.append(atom); cur_len+=L; idx+=1; continue
        # doesn't fit
        if L<=width:
            # move to new line if cur has contents
            if cur:
                lines.append(cur); cur=[]; cur_len=0
                continue  # retry same atom on fresh line
            else:
                cur.append(atom); cur_len+=L; idx+=1; continue
        else:
            # word longer than width
            if cur:
                lines.append(cur); cur=[]; cur_len=0; continue
            # split first width chars - need split by visible width, assume ascii / 1 per char for help words (except maybe unicode, approximate by chars)
            # split by characters accumulating width
            piece_text=""; piece_w=0; pos=0
            text=atom.text
            while pos < len(text):
                cw=text_width(text[pos])
                if piece_w+cw>width:
                    break
                piece_text+=text[pos]; piece_w+=cw; pos+=1
            if piece_text=="":
                # width too small for even one char (e.g. width 0) avoid infinite loop
                piece_text=text[0]; pos=1; piece_w=text_width(piece_text)
            piece_atom=Atom(piece_text,atom.style,atom.cid)
            cur.append(piece_atom); lines.append(cur); cur=[]; cur_len=0
            remaining=text[pos:]
            if remaining=="":
                idx+=1
            else:
                queue[idx]=Atom(remaining,atom.style,atom.cid)
            continue
    if cur or not lines:
        lines.append(cur)
    return lines

def render_atom_group(text,style,skin):
    # skin is dict with code_bg,code_fg,heading_fg
    if style=="plain":
        return text
    if style=="bold":
        return S(["\x1b[1m",text,"\x1b[0m"])
    if style=="italic":
        return S(["\x1b[3m",text,"\x1b[0m"])
    if style=="code":
        bg=skin["code_bg"]; fg=skin["code_fg"]
        return S([f"\x1b[48;5;{bg}m",f"\x1b[38;5;{fg}m",text,"\x1b[49m","\x1b[39m"])
    if style=="heading":
        parts=[]
        if skin.get("heading_fg") is not None:
            parts.append(f"\x1b[38;5;{skin['heading_fg']}m")
        parts+=["\x1b[1m","\x1b[4m",text,"\x1b[0m"]
        return S(parts)
    if style=="bullet":
        return S(["\x1b[38;5;240m",text,"\x1b[39m"])
    if style=="border":
        return S(["\x1b[38;5;239m",text,"\x1b[39m"])
    return text

def render_line_atoms(atoms,skin):
    # group by cid+style merging consecutive
    groups=[]
