                lines.append(cur); cur=[]; cur_len=0; idx+=1  # drop space
            continue
        L=atom.vis_len()
        if cur_len+L<=width:
            cur.append(atom); cur_len+=L; idx+=1; continue
        # doesn't fit
        if L<=width:
            # move to new line if cur has contents
            if cur:
                lines.append(cur); cur=[]; cur_len=0
                continue  # retry same atom on fresh line
            else:
                cur.append(atom); cur_len+=L; idx+=1; continue
        else:
            # word longer than width
            if cur:
                lines.append(cur); cur=[]; cur_len=0; continue
            # split first width chars - need split by visible width, assume ascii / 1 per char for help words (except maybe unicode, approximate by chars)
            # split by characters accumulating width
            piece_text=""; piece_w=0; pos=0
            text=atom.text
            while pos < len(text):
                cw=text_width(text[pos])
                if piece_w+cw>width:
                    break
                piece_text+=text[pos]; piece_w+=cw; pos+=1
            if piece_text=="":
                # width too small for even one char (e.g. width 0) avoid infinite loop
                piece_text=text[0]; pos=1; piece_w=text_width(piece_text)
            piece_atom=Atom(piece_text,atom.style,atom.cid)
            cur.append(piece_atom); lines.append(cur); cur=[]; cur_len=0
            remaining=text[pos:]
            if remaining=="":
                idx+=1
            else:
                queue[idx]=Atom(remaining,atom.style,atom.cid)
            continue
    if cur or not lines:
        lines.append(cur)
    return lines

def render_atom_group(text,style,skin):
    # skin is dict with code_bg,code_fg,heading_fg
    if style=="plain":
        return text
    if style=="bold":
        return S(["\x1b[1m",text,"\x1b[0m"])
    if style=="italic":
        return S(["\x1b[3m",text,"\x1b[0m"])
    if style=="code":
        bg=skin["code_bg"]; fg=skin["code_fg"]
        return S([f"\x1b[48;5;{bg}m",f"\x1b[38;5;{fg}m",text,"\x1b[49m","\x1b[39m"])
    if style=="heading":
        parts=[]
        if skin.get("heading_fg") is not None:
            parts.append(f"\x1b[38;5;{skin['heading_fg']}m")
        parts+=["\x1b[1m","\x1b[4m",text,"\x1b[0m"]
        return S(parts)
    if style=="bullet":
        return S(["\x1b[38;5;240m",text,"\x1b[39m"])
    if style=="border":
        return S(["\x1b[38;5;239m",text,"\x1b[39m"])
    return text

def render_line_atoms(atoms,skin):
    # group by cid+style merging consecutive
    groups=[]
    for atom in atoms:
        if groups and groups[-1][0]==atom.cid and groups[-1][1]==atom.style:
            groups[-1][2]+=atom.text
        else:
            groups.append([atom.cid,atom.style,atom.text])
    out=""
    for _cid,style,text in groups:
        out+=render_atom_group(text,style,skin)
    return out

def line_visible_len(atoms):
    return sum(a.vis_len() for a in atoms)

def get_help_skin():
    luma=luma_for_help()
    if luma is not None and luma<0.2:
        return {"code_bg":237,"code_fg":252,"heading_fg":254}
    if luma is not None and luma>0.85:
        return {"code_bg":252,"code_fg":236,"heading_fg":232}
    return {"code_bg":235,"code_fg":249,"heading_fg":None}

def wrap_compounds(compounds,width):
    atoms=compounds_to_atoms(compounds)
    return wrap_atoms(atoms,width)

def render_paragraph(compounds,width,skin):
    lines=wrap_compounds(compounds,width)
    out_lines=[]
    for atoms in lines:
        out_lines.append(render_line_atoms(atoms,skin))
    return out_lines

def table_col_widths(total_width):
    W=total_width
    if W>=110:
        return [8,30,68]
    if W<=12:
        # minimal 3 each, table will be truncated by rendering ? use 3,3,3
        return [3,3,3]
    if W==13:
        return [3,3,3]
    # piecewise based on observed
    if W<=26:
        # for 14..26 col1 4 , col3 3, col2 remainder ; for 13 already handled
        return [4, W-11, 3]
    if W<=61:
        return [4,15,W-23]
    if W<=65:
        return [W-57,15,38]
    if W<=80:
        return [8,W-50,38]
    # 81..109
    return [8,30,W-42]

def render_table_cell(cell_compounds_by_segment,col_width,align,skin):
    # cell_compounds_by_segment: list of segments (each segment is list of Compound) separated by hard breaks
    all_lines_atoms=[]
    for seg in cell_compounds_by_segment:
        if not seg:
            all_lines_atoms.append([])
            continue
        atoms=compounds_to_atoms(seg)
        lines=wrap_atoms(atoms,col_width)
        all_lines_atoms.extend(lines)
    rendered=[]
    for atoms in all_lines_atoms:
        vis=line_visible_len(atoms)
        if vis>col_width:
            # Shouldn't happen due wrap, but truncate atoms? leave as is
            vis=col_width
        if align=="center":
            left=(col_width-vis)//2
            right=col_width-vis-left
        elif align=="right":
            left=col_width-vis; right=0
        else:
            left=0; right=col_width-vis
        rendered.append(" "*left + render_line_atoms(atoms,skin) + " "*right)
    if not rendered:
        rendered=[" "*col_width]
    return rendered

def render_help_text():
    width=help_width()
    skin=get_help_skin()
    out=[]
    # Title: compounds broot , space , version - all heading
    title_comps=[Compound("broot","heading"),Compound(" ","heading"),Compound(VERSION,"heading")]
    title_lines_atoms=wrap_compounds(title_comps,width)
    for atoms in title_lines_atoms:
        vis=line_visible_len(atoms)
        left=max(0,(width-vis)//2)
        out.append(" "*left+render_line_atoms(atoms,skin))
    out.append("")
    out.append("")
    def para(comps):
        lines=render_paragraph(comps,width,skin)
        out.extend(lines)
    # Paragraph1
    para([Compound("broot","bold"),Compound(" lets you explore file hierarchies with a tree-like view, manipulate and preview files, launch actions, and define your own shortcuts.")])
    out.append("")
    para([Compound("broot","bold"),Compound(" is best launched as "),Compound("br","code"),Compound(": this shell function gives you access to more commands, especially "),Compound("cd.","code"),Compound(" The br shell function is interactively installed on first broot launch.")])
    out.append("")
    para([Compound("Flags and options can be classically passed on launch but also written in the configuration file. Each flag has a counter-flag so that you can cancel at command line a flag which has been set in the configuration file.")])
    out.append("")
    para([Compound("Complete documentation and tips at https://dystroy.org/broot")])
    out.append("")
    # Usage paragraph
    para([Compound("Usage: ","bold"),Compound(" "),Compound("broot","code"),Compound(" [options]","code"),Compound(" [ROOT]","code")])
    out.append("")
    # Bullet item
    # wrap bullet content with width-2
    bullet_comps=[Compound("ROOT","code"),Compound(" : Root Directory")]
    bullet_lines=wrap_compounds(bullet_comps, max(1,width-2))
    for bi,atoms in enumerate(bullet_lines):
        rendered=render_line_atoms(atoms,skin)
        if bi==0:
            out.append(render_atom_group("•","bullet",skin)+" "+rendered)
        else:
            out.append("  "+rendered)
    out.append("")
    out.append(render_atom_group("Options:","bold",skin))
    # Table
    col_widths=table_col_widths(width)
    # if total table width > width for very small widths, we will truncate each rendered line later to width visible? For now use widths as above (W>=13 table totals W)
    def border_line(left,mid,right):
        parts=[]
        parts.append(render_atom_group(left,"border",skin))
        for idx,cw in enumerate(col_widths):
            parts.append(render_atom_group("─"*cw,"border",skin))
            if idx < len(col_widths)-1:
                parts.append(render_atom_group(mid,"border",skin))
        parts.append(render_atom_group(right,"border",skin))
        return "".join(parts)
    # header
    header_cells=[
        ([Compound("short")],"center"),
        ([Compound("long")],"center"),
        ([Compound("description")],"left"),
    ]
    # helper to render a row (list of (segments,align))
    def render_row(cells):
        # cells is list of (segments,align) where segments is list of segments
        rendered_cells=[]
        max_lines=1
        for (segments,align),cw in zip(cells,col_widths):
            rc=render_table_cell(segments,cw,align,skin)
            rendered_cells.append(rc)
            max_lines=max(max_lines,len(rc))
        row_lines=[]
        for li in range(max_lines):
            line=""
            for ci,rc in enumerate(rendered_cells):
                line+=render_atom_group("│","border",skin)
                if li < len(rc):
                    line+=rc[li]
                else:
                    line+=" "*col_widths[ci]
            line+=render_atom_group("│","border",skin)
            row_lines.append(line)
        return row_lines
    out.append(border_line("┌","┬","┐"))
    # header row: segments format
    header_render_cells=[([[c] for c in [Compound("short")]],"center"),([[Compound("long")]],"center"),([[Compound("description")]],"left")]
    # render_table_cell expects list of segments (each list of compounds). For header, one segment each
    out.extend(render_row([([[Compound("short")]],"center"),([[Compound("long")]],"center"),([[Compound("description")]],"left")]))
    out.append(border_line("├","┼","┤"))
    # body rows
    for opt in CLI_OPTIONS:
        short=opt[0]; long=opt[1]; valname=opt[2]; desc=opt[3]
        # short cell
        if short:
            short_plain=f"-{short} "
            short_italic=valname if (short=="c" and valname) else ""
        else:
            short_plain=""
            short_italic=""
        # special: if short exists but italic empty, plain still has trailing space as above. If no short, plain "" and italic "" - atoms will be just empty italic
        short_comps=[]
        if short_plain:
            short_comps.append(Compound(short_plain))
        short_comps.append(Compound(short_italic,"italic"))
        long_plain=f"--{long} "
        long_italic=valname if valname else ""
        long_comps=[Compound(long_plain),Compound(long_italic,"italic")]
        # description segments
        desc_segments=[]
        if long=="verb-output":
            desc_segments=[[Compound("Optional path for verbs using "),Compound(":write_output","code")]]
        elif long=="color":
            desc_segments=[
                [Compound("Whether to have styles and colors")],
                [Compound(" Possible values: ["),Compound("auto","code"),Compound(", "),Compound("yes","code"),Compound(", "),Compound("no","code"),Compound("]")],
                [Compound(" Default: "),Compound("auto","code")],
            ]
        elif long=="set-install-state":
            desc_segments=[
                [Compound("Manually set installation state")],
                [Compound(" Possible values: ["),Compound("undefined","code"),Compound(", "),Compound("refused","code"),Compound(", "),Compound("installed","code"),Compound("]")],
            ]
        else:
            desc_segments=[[Compound(desc)]]
        cells=[
            ([short_comps],"center"),
            ([long_comps],"left"),
            (desc_segments,"left"),
        ]
        out.extend(render_row(cells))
    out.append(border_line("└","┴","┘"))
    # If table total width > width (small widths), termimad would truncate lines? We attempt to truncate visible width while keeping ANSI intact for width<13 cases only as approximation: skip for now if width>=13 table fits exactly
    text="\n".join(out)+"\n\n"
    return text

PYEOF
