# ---------------- config path helpers ----------------

def config_dir_path():
    v=os.environ.get("BROOT_CONFIG_DIR")
    if v:
        return Path(v).expanduser()
    xdg=os.environ.get("XDG_CONFIG_HOME")
    if xdg:
        return Path(xdg).expanduser()/"broot"
    home=os.environ.get("HOME")
    if home:
        return Path(home)/".config"/"broot"
    return Path.home()/".config"/"broot"

def data_dir_path():
    xdg=os.environ.get("XDG_DATA_HOME")
    if xdg:
        return Path(xdg).expanduser()/"broot"
    home=os.environ.get("HOME")
    if home:
        return Path(home)/".local"/"share"/"broot"
    return Path.home()/".local"/"share"/"broot"

def home_dir_path():
    home=os.environ.get("HOME")
    if home:
        return Path(home)
    return Path.home()

def expand_home_str(s):
    # expand ~ at start
    if s=="~":
        return str(home_dir_path())
    if s.startswith("~/"):
        return str(home_dir_path()/s[2:])
    return s

def write_default_conf_to(target_dir_str):
    # Returns None on success, raises BroootError with stderr message formatting done by caller
    target=Path(target_dir_str)
    # Check existing path is a file
    try:
        if target.exists() and not target.is_dir():
            # message exactly 'IO Error : "/path" isn\'t a directory\n'
            raise BroootError(f'IO Error : "{target_dir_str}" isn\'t a directory\n')
        # create dirs
        target.mkdir(parents=True, exist_ok=True)
        # write files
        for rel, content in DEFAULT_CONF_FILES.items():
            dest=target/rel
            dest.parent.mkdir(parents=True, exist_ok=True)
            # overwrite?
            with open(dest,"wb") as f:
                f.write(content)
    except BroootError:
        raise
    except OSError as e:
        # format IO Error : <strerror> (os error N)
        raise BroootError(io_error_msg(e))
    return None

def launcher_dir():
    return config_dir_path()/"launcher"

INSTALLED_FILE_CONTENT=b"\nThis file tells broot the installation of the br function was done.\nIf there's a problem and you want to install it again run\n    broot -- install\n"
REFUSED_FILE_CONTENT=b"\nThis file tells broot you refused the installation of the companion shell function.\nIf you want to install it run\n    broot -- install\n"

def get_install_state():
    ld=launcher_dir()
    if (ld/"installed-v4").exists():
        return "installed"
    if (ld/"refused").exists():
        return "refused"
    return "undefined"

def remove_file_with_message(path):
    # If file/symlink exists, print Removing ... and remove it. Returns True if removed
    try:
        # use lexists (symlink)
        if os.path.lexists(path):
            out_write(f"Removing {code_fixed(str(path))}.\n")
            os.unlink(path)
            return True
    except OSError:
        pass
    return False

def set_install_state(new_state):
    ld=launcher_dir()
    # first remove existing state files - which ones? Observed: it removes installed-v4 if it exists else refused if exists. If both exist? Need check order later; implement: if installed exists remove it, elif refused exists remove it (matches observed single file cases). But what if both? We'll remove first encountered in order [installed-v4, refused] and only one message? Let's keep that.
    # Actually test with both files later; for now remove only the first existing among installed/refused to match single message cases where tie?
    # Ladder: In observed transitions, current state was either installed or refused, and exactly that file was removed.
    # If we simply remove both, we'd print two Removing lines if both exist - might be actually what ref does (it may call remove_install_state_files which iterates). We'll iterate both but need test later.
