# ---------------- Hjson parser ----------------
class HjsonError(Exception):
    def __init__(self,kind,pos,text):
        self.kind=kind; self.pos=pos; self.text=text
    def formatted(self,path):
        # compute line col
        text=self.text; pos=min(self.pos,len(text))
        line=text.count("\n",0,pos)+1
        last_nl=text.rfind("\n",0,pos)
        col=pos-last_nl
        snippet=text[pos:pos+15]
        # rust debug string
        esc=""
        for ch in snippet:
            if ch=="\n": esc+="\\n"
            elif ch=="\r": esc+="\\r"
            elif ch=="\t": esc+="\\t"
            elif ch=='"': esc+='\\"'
            elif ch=="\\": esc+="\\\\"
            elif ord(ch)<0x20:
                esc+=f"\\u{{{ord(ch):x}}}"
            else:
                esc+=ch
        return f'Bad configuration file "{path}" : unable to parse Hjson: {self.kind} at {line}:{col} at "{esc}"\n'

class HjsonParser:
    def __init__(self,text):
        self.s=text; self.n=len(text); self.i=0
    def fail(self,kind,pos=None):
        raise HjsonError(kind, self.i if pos is None else pos, self.s)
    def peek(self):
        return self.s[self.i] if self.i<self.n else ""
    def eof(self):
        return self.i>=self.n
    def skip_ws_comments(self, allow_newline=True):
        while self.i<self.n:
            c=self.s[self.i]
            if c in " \t\r" or (allow_newline and c=="\n"):
                self.i+=1; continue
            if c=="#":
                # to EOL
                while self.i<self.n and self.s[self.i]!="\n": self.i+=1
                continue
            if c=="/" and self.i+1<self.n and self.s[self.i+1]=="/":
                while self.i<self.n and self.s[self.i]!="\n": self.i+=1
                continue
            if c=="/" and self.i+1<self.n and self.s[self.i+1]=="*":
                end=self.s.find("*/",self.i+2)
                if end==-1:
                    self.i=self.n; self.fail("Eof",self.n)
                self.i=end+2; continue
            break
    def skip_inline_ws(self):
        # spaces/tabs but not newline, also comments? comments would go to EOL, treat as newline encountered
        while self.i<self.n and self.s[self.i] in " \t\r":
            self.i+=1
    def parse(self):
        self.skip_ws_comments(True)
        if self.eof():
            return {}
        c=self.peek()
        if c=="{":
            val=self.parse_object_braced()
            self.skip_ws_comments(True)
            if not self.eof():
                self.fail("UnexpectedChar")
            return val
        if c=="[":
            # root array as config -> UnexpectedChar at 1:1 per reference (config expects map)
            self.fail("UnexpectedChar",self.i)
        # root could be scalar? reference errors for 123/"hello" as Eof - we approximate by parsing as implicit object and handling.
        # If first token is a quoted string or number and next non-inline chars are newline/EOF (no colon), reference gives Eof at EOF. Our implicit object parsing will try to read key until colon/newline; quoted string key followed by newline would give ExpectedMapColon - divergence for that rare malformed case. We'll special case: if c is '"' or digit or '-' or '\'' and no colon on same line before newline, then consume value (?) and fail Eof at EOF to match observed scalar cases.
        # Check if there's a colon on first line ( outside quotes ) - simple scan for ':' before '\n' - if not, treat as scalar root error Eof.
        # But files starting with a comment then key... skip already done to first content. Find first newline
        line_end=self.s.find("\n",self.i)
        first_line=self.s[self.i: line_end if line_end!=-1 else self.n]
        if ":" not in first_line:
            # consume till EOF (?) reference reports Eof at EOF for 123 and "hello" files, and UnexpectedChar for [] handled, ExpectedMapColon for 'a 1' (has no colon on first line but gave ExpectedMapColon!)
            # distinction: 'a 1' starts with a letter key - ExpectedMapColon, scalar numbers/strings -> Eof
            if c=='"' or c=="'" or c.isdigit() or c in "-+":
                # seek EOF
                self.i=self.n; self.fail("Eof",self.n)
            # else fallthrough to object parsing which will raise ExpectedMapColon at newline
        val=self.parse_object_implicit()
        return val
    def parse_object_implicit(self):
        obj={}
        while True:
            self.skip_ws_comments(True)
            # commas as separators in implicit? skip commas too? In root implicit, commas maybe not used. Skip them in loop top via if peek ==',' consume and continue
            if self.peek()==",":
