            key_text=self.s[start:self.i].strip()
            if key_text=="":
                # colon at start - unexpected char ?
                self.fail("UnexpectedChar",start)
            self.i+=1  # consume :
            return key_text
    def parse_quoted_string(self):
        quote=self.peek()
        if quote=='"' :
            return self.parse_json_string()
        elif quote=="'":
            if self.s[self.i:self.i+3]=="'''":
                return self.parse_multiline_string()
            else:
                return self.parse_single_quoted()
        else:
            self.fail("UnexpectedChar")
    def parse_json_string(self):
        # starts with "
        self.i+=1; out=[]
        while True:
            if self.eof():
                self.fail("Eof",self.n)
            c=self.s[self.i]
            if c=='"':
                self.i+=1; return "".join(out)
            if c=="\n":
                # unclosed string in JSON would be ??? Deser hjson gives Eof at EOF for '"unclosed\n' because it continues searching for closing quote across newline till EOF
                out.append(c); self.i+=1; continue
            if c=="\\":
                self.i+=1
                if self.eof(): self.fail("Eof",self.n)
                e=self.s[self.i]; self.i+=1
                if e=='"': out.append('"')
                elif e=="\\": out.append("\\")
                elif e=="/": out.append("/")
                elif e=="b": out.append("\b")
                elif e=="f": out.append("\f")
                elif e=="n": out.append("\n")
                elif e=="r": out.append("\r")
                elif e=="t": out.append("\t")
                elif e=="u":
                    if self.i+4>self.n: self.fail("Eof",self.n)
                    hexpart=self.s[self.i:self.i+4]
                    try: code=int(hexpart,16)
                    except: code=0xfffd
                    self.i+=4
