def parse_hjson_file(path):
    # returns dict
    try:
        data=Path(path).read_bytes()
    except OSError as e:
        raise BroootError(io_error_msg(e))
    try:
        text=data.decode('utf-8')
    except Exception:
        text=data.decode('utf-8',errors='replace')
    # Strip BOM?
    if text.startswith("\ufeff"):
        text=text[1:]
    parser=HjsonParser(text)
    try:
        result=parser.parse()
    except HjsonError as he:
        raise BroootError(he.formatted(path))
    if not isinstance(result,dict):
        # config must be a map - reference maybe errors differently, but root scalars already handled as parse errors in parser
        # If result is something else, treat as empty?
        return {}
    return result

