# ---------------- TOML parsing (minimal / using tomllib when available) ----------------
def parse_toml_file(path):
    try:
        data=Path(path).read_bytes()
    except OSError as e:
        raise BroootError(io_error_msg(e))
    # Try stdlib / tomli
    toml_mod=None
    try:
        import tomllib as toml_mod
    except Exception:
        try:
            import tomli as toml_mod
        except Exception:
            toml_mod=None
    if toml_mod is not None:
        try:
            return toml_mod.loads(data.decode('utf-8'))
        except Exception as e:
            # tomllib error message format differs from Rust toml crate. Approximate rust format by extracting line/col if present
            # tomli errors are like "Invalid statement ... (at line 1, column 7)"
            msg=str(e)
            # Try produce a Rust-like message for common cases - fallback to generic with tomllib msg included in a format close to reference
            # Reference prefix: Bad configuration file "<path>" : unable to parse TOML: TOML parse error at line X, column Y\n  |\nX | <line>\n  | <spaces>^\n<detail>\n
            # We'll attempt parse line/col from msg if available
            m=re.search(r'line (\d+), column (\d+)',msg)
            if m:
                line_no=int(m.group(1)); col_no=int(m.group(2))
                lines=data.decode('utf-8',errors='replace').splitlines()
                line_text=lines[line_no-1] if 0<line_no<=len(lines) else ""
                detail=msg
                # strip parenthetical at ...
                detail=re.sub(r'\s*\(at line.*\)\s*$','',detail)
                # Map tomli detail phrases to roughly rust ones for common cases (best effort)
                raise BroootError(f'Bad configuration file "{path}" : unable to parse TOML: TOML parse error at line {line_no}, column {col_no}\n  |\n{line_no} | {line_text}\n  | {" "*(col_no-1)}^\n{detail}\n')
            raise BroootError(f'Bad configuration file "{path}" : unable to parse TOML: {msg}\n')
    # fallback minimal parser (not implemented fully)
    raise BroootError(f'Bad configuration file "{path}" : unable to parse TOML: TOML parse error\n')

def load_one_config_file(path_str, config_state, loaded_files_stack=None):
    # path_str: str as given (could be expanded?) Returns None, updates config_state merged dict
    # Read file first to produce IO error before extension check (as reference)
    # Determine if file is directory etc: reading will give Is a directory error.
    p=Path(path_str)
    try:
        raw_bytes=p.read_bytes()
    except OSError as e:
        raise BroootError(io_error_msg(e))
    ext=p.suffix.lower()
    if ext not in (".hjson",".toml"):
        raise BroootError(f'Bad configuration: unexpected file extension in "{path_str}"\n')
    if ext==".hjson":
        data=parse_hjson_file(path_str)  # rereads file, fine
    else:
        data=parse_toml_file(path_str)
    # data is dict
    config_state['files'].append(str(p))
    # Merge data into state *before* imports (imports then can override)
    merge_config_data(config_state, data, base_dir=p.parent)
    # Now process imports if present in *this* file's data
    imports=data.get("imports") if isinstance(data,dict) else None
    if imports is None:
        imports=data.get("import") if isinstance(data,dict) else None
    if isinstance(imports,list):
        for imp in imports:
            imp_path=None; luma_cond=None
            if isinstance(imp,str):
                imp_path=imp
            elif isinstance(imp,dict):
                # keys file, luma (normalize -/_)
                imp_path=imp.get("file")
                luma_cond=imp.get("luma")
            else:
                continue
            if not isinstance(imp_path,str):
                continue
            if luma_cond is not None:
                # Normalize to list of strings
                cond_list=[]
                if isinstance(luma_cond,str): cond_list=[luma_cond]
                elif isinstance(luma_cond,list): cond_list=[str(x) for x in luma_cond]
                cat=config_luma_category()
                if cat not in cond_list:
                    continue
            # resolve relative to current file's dir, expand ~ 
            ip_str=expand_home_str(imp_path)
            ip=Path(ip_str)
            if not ip.is_absolute():
                ip=(p.parent/ip).resolve() if False else (p.parent/ip)
                # Use absolute normalized path for loading, but preserve as string without resolving symlinks? Path may contain .. etc. Use os.path.normpath
                ip=Path(os.path.normpath(str(ip)))
            # Protect against cycles
            if loaded_files_stack is not None and str(ip) in loaded_files_stack:
                continue
            new_stack=(loaded_files_stack or [])+[str(p)]
            load_one_config_file(str(ip), config_state, loaded_files_stack=new_stack)

def normalize_key(k):
    return k.replace("-","_") if isinstance(k,str) else k

def merge_config_data(state,data,base_dir=None):
    if not isinstance(data,dict):
