    'black':0,'darkred':1,'darkgreen':2,'darkyellow':3,'darkblue':4,'darkmagenta':5,'darkcyan':6,'grey':7,'gray':7,'darkgrey':8,'darkgray':8,
    'red':9,'green':10,'yellow':11,'blue':12,'magenta':13,'cyan':14,
    # white parsed from skin strings gives 231 in reference (see notes), handled as special in parser
}
CSS_NAMED_RGB={
    'white':(255,255,255),'black':(0,0,0),'red':(255,0,0),'green':(0,128,0),'lime':(0,255,0),'blue':(0,0,255),'yellow':(255,255,0),'cyan':(0,255,255),'aqua':(0,255,255),'magenta':(255,0,255),'fuchsia':(255,0,255),
    'orange':(255,165,0),'pink':(255,192,203),'purple':(128,0,128),'brown':(165,42,42),'silver':(192,192,192),'gold':(255,215,0),'violet':(238,130,238),'indigo':(75,0,130),'turquoise':(64,224,208),'salmon':(250,128,114),'khaki':(240,230,140),'beige':(245,245,220),'ivory':(255,255,240),'coral':(255,127,80),'crimson':(220,20,60),'lavender':(230,230,250),'skyblue':(135,206,235),'seagreen':(46,139,87),'olive':(128,128,0),'maroon':(128,0,0),'navy':(0,0,128),'teal':(0,128,128),'gray':(128,128,128),'grey':(128,128,128),
}

def ansi256_palette_rgb(n):
    if n<16:
        # xterm system colours approximation (for distance calculation)
        table=[(0,0,0),(205,0,0),(0,205,0),(205,205,0),(0,0,238),(205,0,205),(0,205,205),(229,229,229),(127,127,127),(255,0,0),(0,255,0),(255,255,0),(92,92,255),(255,0,255),(0,255,255),(255,255,255)]
        return table[n]
    if n>=232:
        v=8+(n-232)*10; return (v,v,v)
    n2=n-16; r=(n2//36)%6; g=(n2//6)%6; b=n2%6
    def conv(x): return 0 if x==0 else 55+40*x
    return (conv(r),conv(g),conv(b))

def rgb_to_ansi256(r,g,b):
    best=0; best_dist=None
    for i in range(256):
        pr,pg,pb=ansi256_palette_rgb(i)
        d=(r-pr)**2+(g-pg)**2+(b-pb)**2
        if best_dist is None or d<best_dist:
            best_dist=d; best=i
            if d==0:
                # white special case: exact matches at 15 and 231 - reference parsed white gave 231, but this loop would break at 15. To mimic, continue searching for white exact case ?
                pass
    # special case (255,255,255) -> 231 to match parsed skin behaviour
    if (r,g,b)==(255,255,255):
        return 231
    return best

def parse_color_token(tok):
    # returns colour tuple or None for 'none', raises ValueError if not recognised
    low=tok.lower()
    if low=="none":
        return None
    m=re.fullmatch(r'ansi\((\d+)\)',low)
    if m:
        return ('ansi',int(m.group(1))%256)
    m=re.fullmatch(r'(?:gray|grey)\((\d+)\)',low)
    if m:
        n=int(m.group(1)); return ('ansi',232+n)
    m=re.fullmatch(r'rgb\((.*)\)',tok,re.I)
    if m:
        inner=m.group(1)
        parts=[p.strip() for p in inner.split(',')]
        if len(parts)!=3:
            raise ValueError(tok)
        try:
            r,g,b=[int(p) for p in parts]
        except:
            raise ValueError(tok)
        return ('rgb',r,g,b)
    if tok.startswith('#'):
        h=tok[1:]
        if re.fullmatch(r'[0-9a-fA-F]{3}',h):
            r=int(h[0]*2,16); g=int(h[1]*2,16); b=int(h[2]*2,16); return ('rgb',r,g,b)
        if re.fullmatch(r'[0-9a-fA-F]{6}',h):
            return ('rgb',int(h[0:2],16),int(h[2:4],16),int(h[4:6],16))
        raise ValueError(tok)
    if low=='white':
        return ('ansi',231)
    if low in NAMED_COLORS_ANSI:
        return ('ansi',NAMED_COLORS_ANSI[low])
    if low in CSS_NAMED_RGB:
        rgb=CSS_NAMED_RGB[low]; return ('rgb',rgb[0],rgb[1],rgb[2])
    raise ValueError(tok)

ATTR_CODES={
    'bold':1,'dim':2,'italic':3,'underlined':4,'underline':4,'reverse':7,'hidden':8,'crossedout':9,'crossed_out':9,'strikethrough':9,'overlined':53,'overline':53,
}

class SkinStyle:
    __slots__=("fg","bg","attrs")
    def __init__(self,fg=None,bg=None,attrs=None):
        self.fg=fg; self.bg=bg; self.attrs=set(attrs) if attrs else set()
    def __repr__(self):
        return f"Style(fg={self.fg},bg={self.bg},attrs={self.attrs})"

def tokenize_skin_part(part):
    tokens=[]; i=0
    while i < len(part):
        if part[i].isspace():
            i+=1; continue
        start=i; depth=0
        while i < len(part):
            ch=part[i]
            if ch=='(':
                depth+=1
            elif ch==')':
                depth-=1
            elif depth==0 and ch.isspace():
                break
            i+=1
        tokens.append(part[start:i])
    return tokens

def parse_skin_style(value_str):
    # returns (active_style, inactive_style) where each is SkinStyle
    if not isinstance(value_str,str):
        value_str=str(value_str)
    parts=value_str.split('/')
    # Note: a colour like rgb contains no slash; ext etc. If more than 2 parts due to ??? join extras? Skin values should have at most one slash separator. If more, first slash separates?
    def parse_part(part):
        tokens=tokenize_skin_part(part.strip())
        fg='UNSET'; bg='UNSET'; attrs=set()
        # tokens: first colour tokens up to 2, rest attrs; but a token could be attr if colour missing? Check if token is attribute name before treating as colour
        idx=0
        colours=[]
        while idx < len(tokens):
            tok=tokens[idx]
            low=tok.lower()
            if low in ATTR_CODES:
                attrs.add(ATTR_CODES[low]); idx+=1; continue
            # try colour
            try:
                c=parse_color_token(tok)
            except Exception:
                raise ValueError(f"{tok} not recognized as a style token")
            colours.append(c); idx+=1
            if len(colours)>=2:
                # remaining must be attrs
                continue
        fg=colours[0] if len(colours)>=1 else None
        bg=colours[1] if len(colours)>=2 else None
        return SkinStyle(fg,bg,attrs)
    active=parse_part(parts[0]) if parts else SkinStyle()
    if len(parts)>1:
        inactive=parse_part('/'.join(parts[1:]))
    else:
        inactive=SkinStyle(active.fg,active.bg,set(active.attrs))
    return (active,inactive)

# base skin defaults (approximation based on dark-blue file)
def load_base_skin():
    # parse skins/dark-blue.hjson from embedded defaults as base, then adjustments
    skin={}
    try:
        # Use embedded file content parsing via HjsonParser directly on bytes
        content=DEFAULT_CONF_FILES.get('skins/dark-blue.hjson',b'').decode('utf-8')
        data=HjsonParser(content).parse()
        raw=data.get('skin',{}) if isinstance(data,dict) else {}
        for k,v in raw.items():
            try:
                skin[k]=parse_skin_style(v)
            except Exception:
                pass
    except Exception:
        pass
    # Adjust default bg to gray(2) (observed built-in)
    if 'default' in skin:
        act,ina=skin['default']
        # active bg originally none, set to gray2 ansi 234 if bg is None
        if act.bg is None:
            act.bg=('ansi',234)
        if ina.bg is None:
            ina.bg=('ansi',234)
    # Adjust input fg to ansi 15 for built-in (parsed white would be 231; base hard-coded is 15)
    if 'input' in skin:
        act,ina=skin['input']
        if act.fg==('ansi',231):
            act.fg=('ansi',15)
    return skin

_BASE_SKIN_CACHE=None
def get_base_skin():
    global _BASE_SKIN_CACHE
    if _BASE_SKIN_CACHE is None:
        _BASE_SKIN_CACHE=load_base_skin()
    # return deep copy per call to avoid mutation
    out={}
    for k,(a,b) in _BASE_SKIN_CACHE.items():
        out[k]=(SkinStyle(a.fg,a.bg,set(a.attrs)),SkinStyle(b.fg,b.bg,set(b.attrs)))
    return out

def resolve_skin(config_state):
    skin=get_base_skin()
    raw=config_state.get('skin',{}) if isinstance(config_state,dict) else {}
    if isinstance(raw,dict):
        for k,v in raw.items():
            # v may be string (from config) or (if from merged state where raw may have been stored?) Our merge_config_data stores skin values as strings (original values)
            try:
                if isinstance(v,str):
                    skin[k]=parse_skin_style(v)
                else:
                    # maybe value could be something else? ignore
                    pass
            except Exception as e:
                # reference would error during config deserialization - we already would have only accepted valid configs, ignore here
                pass
    return skin

def color_to_ansi_code(colour,is_bg,true_colors=False):
    # returns escape sequence string (before NO_COLOR transform) like \x1b[38;5;{n}m or truecolour
    if colour is None:
        return None
    if colour[0]=='ansi':
        n=colour[1]
        return f"\x1b[{'48' if is_bg else '38'};5;{n}m"
    if colour[0]=='rgb':
        r,g,b=colour[1],colour[2],colour[3]
        if true_colors:
            return f"\x1b[{'48' if is_bg else '38'};2;{r};{g};{b}m"
        else:
            n=rgb_to_ansi256(r,g,b)
            return f"\x1b[{'48' if is_bg else '38'};5;{n}m"
    return None

def is_true_colors_enabled(config_state):
    # config true_colors key if present
    if isinstance(config_state,dict) and 'true_colors' in config_state:
        v=config_state['true_colors']
        if isinstance(v,bool):
            return v
    ct=os.environ.get("COLORTERM","")
    if "24bit" in ct or "truecolor" in ct:
        return True
    return False

def render_styled_chunk(text, effective_style, style_enabled=True, true_colors=False):
    if not style_enabled:
        return text
    if effective_style is None:
        return text
    fg=effective_style.fg; bg=effective_style.bg; attrs=effective_style.attrs
    if fg is None and bg is None and not attrs:
        return text
    before=[]
    if bg is not None:
        code=color_to_ansi_code(bg,True,true_colors)
        if code: before.append(code)
    if fg is not None:
        code=color_to_ansi_code(fg,False,true_colors)
        if code: before.append(code)
    for attr in sorted(attrs):
        before.append(f"\x1b[{attr}m")
    after=[]
    if attrs:
        after.append("\x1b[0m")
    else:
        if bg is not None:
            after.append("\x1b[49m")
        if fg is not None:
            after.append("\x1b[39m")
    # Apply NO_COLOR transformation to each code
    def tr(code):
        return esc_seq(code)
    return "".join(tr(c) for c in before)+text+"".join(tr(c) for c in after)

