def format_size(n):
    try:
        n=int(n)
    except Exception:
        n=0
    if n<10000:
        return str(n)
    units=['','K','M','G','T','P','E']
    value=float(n); idx=0
    while value>=1000 and idx < len(units)-1:
        value/=1000.0; idx+=1
    if idx==0:
        return str(n)
    if value < 10:
        cand=f"{value:.1f}{units[idx]}"
        if len(cand)<=4:
            return cand
        # fall back to integer format for this unit (e.g. 10.0M -> 10M)
        return f"{value:.0f}{units[idx]}"
    else:
        cand=f"{value:.0f}{units[idx]}"
        if len(cand)<=4:
            return cand
        # bump unit
        value/=1000.0; idx+=1
        if idx>=len(units):
            return cand
        cand2=f"{value:.1f}{units[idx]}"
        if len(cand2)>4:
            return f"{value:.0f}{units[idx]}"
        return cand2

