# ---------------- search patterns ----------------

def normalize_for_fuzzy(s):
    # lower case, strip diacritics
    s_n=unicodedata.normalize('NFKD',s)
    out=[]
    for ch in s_n:
        if unicodedata.combining(ch):
            continue
        out.append(ch.lower())
    return "".join(out)

DEFAULT_SEARCH_MODES={
    "": ("fuzzy","path"),
    "/": ("regex","name"),
    "f/": ("fuzzy","name"),
    "e/": ("exact","name"),
    "n/": ("fuzzy","name"),
    "p/": ("fuzzy","path"),
    "r/": ("regex","name"),
    "t/": ("tokens","path"),
    "c/": ("exact","content"),
    "fn/": ("fuzzy","name"), "nf/": ("fuzzy","name"),
    "fp/": ("fuzzy","path"), "pf/": ("fuzzy","path"),
    "en/": ("exact","name"), "ne/": ("exact","name"),
    "ep/": ("exact","path"), "pe/": ("exact","path"),
    "ec/": ("exact","content"), "ce/": ("exact","content"),
    "rn/": ("regex","name"), "nr/": ("regex","name"),
    "rp/": ("regex","path"), "pr/": ("regex","path"),
    "cr/": ("regex","content"),
    "nt/": ("tokens","name"), "tn/": ("tokens","name"),
    "tp/": ("tokens","path"), "pt/": ("tokens","path"),
}

def build_search_modes(config_state):
    modes=dict(DEFAULT_SEARCH_MODES)
    from_config=config_state.get('search_modes') if isinstance(config_state,dict) else None
    if isinstance(from_config,dict):
        for raw_key,raw_value in from_config.items():
            if not isinstance(raw_value,str):
                continue
            # value format "fuzzy name" etc, allow hyphen/underscores?
            parts=raw_value.strip().lower().replace('_',' ').replace('-',' ').split()
            if len(parts)!=2:
                continue
            kind,obj=parts
            if kind not in ("fuzzy","exact","regex","tokens") or obj not in ("name","path","content"):
                continue
            key=str(raw_key)
            if key=="<empty>":
                key=""
            # keys in config may be documented without trailing slash? e.g. "z/" includes slash, "/" is slash, "<empty>" empty.
            # Normalize: if key not empty and not ending with '/', add '/'? But a custom mode key could be something without slash? Search modes map keys are prefixes ending with '/' except empty and '/'
            if key not in ("","/") and not key.endswith("/"):
                key=key+"/"
            modes[key]=(kind,obj)
    return modes

class PatternError(Exception):
    pass

class ElementaryPattern:
    __slots__=("kind","obj","body","flags","regex_obj","tokens")
    def __init__(self,kind,obj,body,flags):
        self.kind=kind; self.obj=obj; self.body=body; self.flags=flags or ""
        self.regex_obj=None; self.tokens=None
        if kind=="regex":
            # translate Rust regex syntax to Python mostly compatible. Rust regex uses \d \w etc supported by python re (unicode classes differences minor)
            flags_re=0
            if "i" in self.flags:
                flags_re|=re.IGNORECASE
            # other flags maybe m,s,x,U etc ignore/ mapping
            if "m" in self.flags: flags_re|=re.MULTILINE
            if "s" in self.flags: flags_re|=re.DOTALL
            if "x" in self.flags: flags_re|=re.VERBOSE
            try:
                self.regex_obj=re.compile(body,flags_re)
            except re.error as e:
                raise PatternError(str(e))
        elif kind=="tokens":
            self.tokens=[t for t in body.split(",") if t!=""] if body!="" else []
    def __repr__(self):
        return f"Elem({self.kind} {self.obj} {self.body!r}/{self.flags})"

# Composite pattern AST nodes as tuples: ('elem',Elementary), ('and',left,right), ('or',...), ('not',node), ('group',node)

class CompositeParser:
    def __init__(self,text,modes):
