    def parse_or(self):
        left=self.parse_and()
        while True:
            if self.peek()=="|":
                self.i+=1
                right=self.parse_and()
                left=('or',left,right)
            else:
                break
        return left
    def parse_and(self):
        left=self.parse_unary()
        while True:
            if self.peek()=="&":
                self.i+=1
                right=self.parse_unary()
                left=('and',left,right)
            else:
                break
