    def parse_unary(self):
        if self.peek()=="!":
            self.i+=1
            node=self.parse_unary()
            return ('not',node)
        if self.peek()=="(":
            self.i+=1
            node=self.parse_or()
            if self.peek()==")":
                self.i+=1
            # If missing ), treat EOF/end as okay
            return node
        # elementary
        elem=self.parse_elementary()
        return ('elem',elem)
    def parse_elementary(self):
        start=self.i
        # scan for first unescaped '/' before a delimiter (&|() or space/colon or EOF)
        j=self.i
