    # DP implementation similar to fzf skim v2 simplified
    # pattern_norm & candidate_norm are strings already normalized (lowercase, diacritics stripped) - they should have same length as original candidate for index mapping (diacritics stripping may change length for some unicode chars (e.g., é -> e+ combining mark removed) - our normalization of candidate_original when composed chars are single codepoints will map 1-1 by decomposing and dropping combining marks - resulting normalized length equals number of base characters, which may be less than original composed length if original was decomposed form in filename (unlikely). For position mapping we assume normalized string indexes correspond to original string indexes for common cases (composed forms decompose to 1 base char from 1 original char)
    p=pattern_norm; t=candidate_norm
    np=len(p); nt=len(t)
    if np==0:
        return (0,[])
    if np>nt:
        # quick subsequence check will fail in DP anyway
        pass
    # Bonus per candidate position
    bonus=[0]*nt
    for i,ch in enumerate(t):
        if i==0:
            bonus[i]=8
        else:
            prev=t[i-1]
            if prev in "/\\_-. :;,":
                bonus[i]=8
            elif prev.islower() and ch.isupper():
                bonus[i]=7
            elif prev.isalpha() and ch.isdigit():
                bonus[i]=7
            elif prev.isdigit() and ch.isalpha():
                bonus[i]=7
            else:
                bonus[i]=0
    # DP tables: D[i][j] score for pattern[0..i] matched ending at text[j] matched, M[i][j] best score up to text[j]
    # Use 2 rows for D and M with backtracking storage for full pattern - to recover alignment we may keep full tables for simplicity if sizes modest.
    # Implement full tables as list of list ints with -inf
    NEG=-10**9
    D=[[NEG]*(nt) for _ in range(np)]
    M=[[NEG]*(nt) for _ in range(np)]
    for i in range(np):
        prev_score=NEG
        gap_penalty = -3 if i==0 else -3 # first gap char
        # Actually fzf gap penalty applies differently in M update
        for j in range(nt):
            if p[i]==t[j]:
                if i==0:
                    score = 16 + bonus[j]*2  # first char multiplier
                    # apply leading gap penalty: j gaps before first match: if j>0, penalize gapStart + (j-1)*gapExt
                    if j>0:
                        score += -3 + (j-1)*(-1)
                    D[i][j]=score
                else:
                    # Option coming from previous match immediately before (consecutive) or from best before
                    # Score from M[i-1][j-1] + match + bonus
                    # Consecutive bonus if previous char was match - handled by considering D[i-1][j-1] special: In fzf, bonus for consecutive is max(bonus[j], BONUS_CONSECUTIVE reward...) - simplify: if coming from D[i-1][j-1] use bonus = max(bonus[j],4)
                    best_prev=M[i-1][j-1] if j>0 else NEG
                    cons_prev=D[i-1][j-1] if j>0 else NEG
                    score_from_best = best_prev + 16 + bonus[j] if best_prev!=NEG else NEG
                    score_from_cons = cons_prev + 16 + max(bonus[j],4) if cons_prev!=NEG else NEG
                    D[i][j]=max(score_from_best,score_from_cons)
            # M
            if j==0:
                M[i][j]=D[i][j]
            else:
