# ---------------- search patterns ----------------

def normalize_for_fuzzy(s):
    # lower case, strip diacritics
    s_n=unicodedata.normalize('NFKD',s)
    out=[]
    for ch in s_n:
        if unicodedata.combining(ch):
            continue
