DEFAULT_SEARCH_MODES={
    "": ("fuzzy","path"),
    "/": ("regex","name"),
    "f/": ("fuzzy","name"),
    "e/": ("exact","name"),
    "n/": ("fuzzy","name"),
    "p/": ("fuzzy","path"),
    "r/": ("regex","name"),
    "t/": ("tokens","path"),
    "c/": ("exact","content"),
    "fn/": ("fuzzy","name"), "nf/": ("fuzzy","name"),
    "fp/": ("fuzzy","path"), "pf/": ("fuzzy","path"),
    "en/": ("exact","name"), "ne/": ("exact","name"),
    "ep/": ("exact","path"), "pe/": ("exact","path"),
    "ec/": ("exact","content"), "ce/": ("exact","content"),
    "rn/": ("regex","name"), "nr/": ("regex","name"),
    "rp/": ("regex","path"), "pr/": ("regex","path"),
    "cr/": ("regex","content"),
    "nt/": ("tokens","name"), "tn/": ("tokens","name"),
    "tp/": ("tokens","path"), "pt/": ("tokens","path"),
}

def build_search_modes(config_state):
    modes=dict(DEFAULT_SEARCH_MODES)
    from_config=config_state.get('search_modes') if isinstance(config_state,dict) else None
    if isinstance(from_config,dict):
        for raw_key,raw_value in from_config.items():
            if not isinstance(raw_value,str):
                continue
            # value format "fuzzy name" etc, allow hyphen/underscores?
            parts=raw_value.strip().lower().replace('_',' ').replace('-',' ').split()
            if len(parts)!=2:
                continue
            kind,obj=parts
            if kind not in ("fuzzy","exact","regex","tokens") or obj not in ("name","path","content"):
                continue
            key=str(raw_key)
            if key=="<empty>":
                key=""
            # keys in config may be documented without trailing slash? e.g. "z/" includes slash, "/" is slash, "<empty>" empty.
            # Normalize: if key not empty and not ending with '/', add '/'? But a custom mode key could be something without slash? Search modes map keys are prefixes ending with '/' except empty and '/'
            if key not in ("","/") and not key.endswith("/"):
                key=key+"/"
            modes[key]=(kind,obj)
    return modes

class PatternError(Exception):
    pass

class ElementaryPattern:
    __slots__=("kind","obj","body","flags","regex_obj","tokens")
    def __init__(self,kind,obj,body,flags):
        self.kind=kind; self.obj=obj; self.body=body; self.flags=flags or ""
        self.regex_obj=None; self.tokens=None
        if kind=="regex":
            # translate Rust regex syntax to Python mostly compatible. Rust regex uses \d \w etc supported by python re (unicode classes differences minor)
            flags_re=0
            if "i" in self.flags:
                flags_re|=re.IGNORECASE
            # other flags maybe m,s,x,U etc ignore/ mapping
            if "m" in self.flags: flags_re|=re.MULTILINE
            if "s" in self.flags: flags_re|=re.DOTALL
            if "x" in self.flags: flags_re|=re.VERBOSE
            try:
                self.regex_obj=re.compile(body,flags_re)
            except re.error as e:
                raise PatternError(str(e))
        elif kind=="tokens":
            self.tokens=[t for t in body.split(",") if t!=""] if body!="" else []
    def __repr__(self):
        return f"Elem({self.kind} {self.obj} {self.body!r}/{self.flags})"

# Composite pattern AST nodes as tuples: ('elem',Elementary), ('and',left,right), ('or',...), ('not',node), ('group',node)

class CompositeParser:
    def __init__(self,text,modes):
        self.s=text; self.n=len(text); self.i=0; self.modes=modes
    def peek(self):
        return self.s[self.i] if self.i<self.n else ""
    def parse(self):
        if self.s.strip()=="":
            return None
        node=self.parse_or()
        # ignore any leftover characters that are closing paren? If there's a stray ) at top level, reference might treat as error - we'll accept leftover and if any remaining non-space chars, mark invalid?
        # Skip trailing spaces expected to be none (pattern string should not have spaces unescaped - input parser handled verb split)
        if self.i < self.n:
            # If rest starts with ) that has no matching (, combination invalid - to mimic maybe raise PatternError
            # But docs say ending characters often unnecessary, extra maybe ... We'll ignore rest?
            # Check what reference does for pattern "a)" later
            pass
        return node
    def parse_or(self):
        left=self.parse_and()
        while True:
            if self.peek()=="|":
                self.i+=1
                right=self.parse_and()
                left=('or',left,right)
            else:
                break
        return left
    def parse_and(self):
        left=self.parse_unary()
        while True:
            if self.peek()=="&":
                self.i+=1
                right=self.parse_unary()
                left=('and',left,right)
            else:
                break
        return left
    def parse_unary(self):
        if self.peek()=="!":
            self.i+=1
            node=self.parse_unary()
            return ('not',node)
        if self.peek()=="(":
            self.i+=1
            node=self.parse_or()
            if self.peek()==")":
                self.i+=1
            # If missing ), treat EOF/end as okay
            return node
        # elementary
        elem=self.parse_elementary()
        return ('elem',elem)
    def parse_elementary(self):
        start=self.i
        # scan for first unescaped '/' before a delimiter (&|() or space/colon or EOF)
        j=self.i
        found_slash=-1
        while j < self.n:
            ch=self.s[j]
            if ch=="\\":
                j+=2; continue
            if ch=="/":
                found_slash=j; break
            if ch in "&|() \t:":
                break
            j+=1
        mode_kind=None; mode_obj=None; body_start=None
        has_prefix=False
        if found_slash!=-1:
            candidate=self.s[start:found_slash+1] if found_slash!=start else "/"
            # candidate key is as typed for "/" case found_slash==start => candidate "/"
            if found_slash==start:
                candidate="/"
            if candidate in self.modes:
                mode_kind,mode_obj=self.modes[candidate]
                has_prefix=True
                body_start=found_slash+1
                self.i=body_start
            else:
                raise PatternError(f"invalid search mode {candidate}")
        else:
            # no slash before delimiter
            mode_kind,mode_obj=self.modes.get("",("fuzzy","path"))
            has_prefix=False
            body_start=start
            self.i=start
        # now parse body
        body_chars=[]
        flags=""
        if not has_prefix:
            # pre-slash state: read until unescaped & | ) ( or EOF. Space/colon should have been delimiters for verb - pattern string could contain them only if caller passed pattern isolated, but treat them as end as well.
            while self.i < self.n:
                ch=self.s[self.i]
                if ch=="\\":
                    if self.i+1 < self.n:
                        nxt=self.s[self.i+1]
                        if nxt in " &|():\\/!":
                            body_chars.append(nxt); self.i+=2
                        else:
                            body_chars.append("\\"); body_chars.append(nxt); self.i+=2
                    else:
                        body_chars.append("\\"); self.i+=1
                    continue
                if ch in "&|)":
                    break
                if ch in " \t:":
                    break
                # '!' and '(' inside a body: treat as literal? In docs operators need escaping, so '(' opening a group after a pattern without operator is ambiguous - treat '(' as a delimiter? But a pattern like "a(b" where '(' unescaped should be operator error-ish. We'll treat '(' as delimiter ending this elementary (following group will be parsed but without operator might be ignored - edge)
                if ch=="(":
                    break
                body_chars.append(ch); self.i+=1
            body="".join(body_chars)
        else:
            # after first slash state
            found_closing=False
            while self.i < self.n:
                ch=self.s[self.i]
                if ch=="\\":
                    if self.i+1 < self.n:
                        nxt=self.s[self.i+1]
                        if nxt in " :\\/":
                            body_chars.append(nxt); self.i+=2
                        else:
                            body_chars.append("\\"); body_chars.append(nxt); self.i+=2
                    else:
                        body_chars.append("\\"); self.i+=1
                    continue
                if ch=="/":
                    found_closing=True; self.i+=1; break
                if ch in " \t:":
                    break
                body_chars.append(ch); self.i+=1
            body="".join(body_chars)
            if found_closing:
                flags_chars=[]
                while self.i < self.n and (self.s[self.i].isalpha()):
                    flags_chars.append(self.s[self.i]); self.i+=1
                flags="".join(flags_chars)
                # after flags, next char should be operator or end - our caller loop handles
            # else flags empty
        # Create elementary - may raise pattern error for bad regex
        if body=="":
            # An empty elementary pattern - treat as a pattern that matches everything? In typing states, e.g. "c/" incomplete - reference likely treats as no filter / incomplete. Mark by raising PatternError with special incomplete flag ??? We'll represent as an elem with empty body matching all with score 0, but outer composite evaluation might need to know it's incomplete to stay unfiltered in TUI interactive state. For --cmd, an empty search phase before a verb is often used (":pt" has empty pattern input altogether, not an elementary with body empty). This parser only invoked when pattern string non empty, a "c/" pattern in a command would be strange. We'll allow empty body matching all.
            pass
        elem=ElementaryPattern(mode_kind,mode_obj,body,flags)
        return elem

def parse_pattern(pattern_str,modes):
    if pattern_str is None or pattern_str=="":
        return None
    parser=CompositeParser(pattern_str,modes)
    return parser.parse()

