def parse_file_size_config(value):
    # value like '10MB', '5GB', '44Kib', number
    if value is None:
        return 10*1000*1000
    if isinstance(value,(int,float)):
        return int(value)
    s=str(value).strip()
    m=re.fullmatch(r'([0-9]+(?:\.[0-9]+)?)\s*([A-Za-z]*)',s)
    if not m:
        # for config validation, reference would have earlier error - for our runtime, default to 10MB if unparsable (validation may occur elsewhere)
        return 10*1000*1000
    num=float(m.group(1)); unit=m.group(2).lower()
    mult=1
    if unit in ("","b"):
        mult=1
    elif unit in ("kb","k","kib"):
        mult=1024 if unit=="kib" else 1000
    elif unit in ("mb","m","mib"):
        mult=1024*1024 if unit=="mib" else 1000*1000
    elif unit in ("gb","g","gib"):
        mult=1024**3 if unit=="gib" else 1000**3
    elif unit in ("tb","t","tib"):
        mult=1024**4 if unit=="tib" else 1000**4
    else:
        return 10*1000*1000
    return int(num*mult)

