# ---------------- tree line rendering ----------------
# A display chunk is tuple (text, SkinStyle effective-ish or skin_key style or special string)
# We will represent chunks as dict/tuple: (text, style_obj) where style_obj is SkinStyle (already resolved fg/bg/attrs possibly None for inherit)

def get_skin_style(skin,key,focused=True):
    pair=skin.get(key)
    if not pair:
        return SkinStyle(None,None,set())
    st=pair[0] if focused else pair[1]
    return SkinStyle(st.fg,st.bg,set(st.attrs))

def merge_bg_fg(style,base_style):
    # style may have None fg/bg - inherit from base_style (default or selected)
    fg=style.fg if style.fg is not None else (base_style.fg if base_style else None)
    bg=style.bg if style.bg is not None else (base_style.bg if base_style else None)
    return SkinStyle(fg,bg,set(style.attrs))

def entry_name_style_key(entry):
    if entry.is_symlink:
        return "link"
    if entry.is_dir_real:
        return "directory"
    if entry.is_executable():
        return "exe"
    return "file"

def entry_effective_name_style(entry,skin,config_state,focused=True):
    key=entry_name_style_key(entry)
    st=get_skin_style(skin,key,focused)
    # ext colour override for non-directory regular files (and symlink target files??)
    if not entry.is_dir_real:
        ext=entry.extension()
        ext_colors=config_state.get('ext_colors') if isinstance(config_state,dict) else None
        if isinstance(ext_colors,dict) and ext in ext_colors:
            try:
                col=parse_color_token(str(ext_colors[ext]).strip())
                if col is not None:
                    st.fg=col
            except Exception:
                pass
    return st

def format_date_for_entry(ts,config_state):
    fmt=config_state.get('date_time_format') if isinstance(config_state,dict) else None
    if not isinstance(fmt,str) or fmt=="":
        fmt="%Y/%m/%d %R"
    # Convert chrono format tokens unsupported by python strftime minimally
    # Replace %R -> %H:%M, %T->%H:%M:%S, %F->%Y-%m-%d, if python version doesn't support them (Linux glibc strftime does support %R,%F,%T - keep)
    try:
        lt=time.localtime(ts)
        return time.strftime(fmt,lt)
    except Exception:
        return time.strftime("%Y/%m/%d %H:%M",time.localtime(ts))

def bar_for_ratio(ratio):
    if ratio is None or ratio<=0:
        return " "*10
    if ratio>1:
        ratio=1
    eighths=int(math.floor(ratio*80+0.5))
    if eighths>80: eighths=80
    full=eighths//8; rem=eighths%8
    partial_chars=["","▏","▎","▍","▌","▋","▊","▉"]
    s="█"*full
    if rem:
        s+=partial_chars[rem]
    if len(s)<10:
        s+=" "*(10-len(s))
    return s[:10]

class LineRenderer:
    def __init__(self,opts,config_state,skin,style_enabled,area_width,root_entry,lines_for_widths):
        self.opts=opts; self.config=config_state; self.skin=skin; self.style_enabled=style_enabled
        self.area_width=max(1,area_width)
        self.root_entry=root_entry
        self.true_colors=is_true_colors_enabled(config_state)
        self.cols_order=self._get_cols_order()
        # compute display columns active booleans
        self.show_sizes_col = bool(opts.show_sizes or opts.sort_mode=='size')
        self.show_dates_col = bool(opts.show_dates or opts.sort_mode=='date')
        self.show_counts_col = bool(getattr(opts,'show_counts',False) or opts.sort_mode=='count')
        self.show_perm_col = bool(opts.show_permissions)
        self.show_git_col = bool(opts.show_git_info or opts.git_status_only)
        self.show_device_col = bool(getattr(opts,'show_device_id',False))
        # >>> column widths that depend on all lines: size and count
        self.size_col_width=0; self.count_col_width=0
        if self.show_sizes_col:
            widths=[]
            # root total formatted
            if root_entry is not None:
                # ensure sums later by caller before renderer creation for lines that need it
                rv=root_entry.sum_size if root_entry.is_dir_real else root_entry.file_display_size()
                if rv is not None:
                    widths.append(len(format_size(rv)))
            for tl in lines_for_widths:
                if tl.is_pruning or tl.entry is None or tl.depth==0:
                    continue
                e=tl.entry
                v=e.sum_size if e.is_dir_real else e.file_display_size()
                if e.is_dir_real and e.sum_size is None:
                    v=0
                widths.append(len(format_size(v or 0)))
            self.size_col_width=max(widths) if widths else 1
        if self.show_counts_col:
            widths=[]
            for tl in lines_for_widths:
                if tl.is_pruning or tl.entry is None or tl.depth==0: continue
                widths.append(len(str(tl.entry.sum_count or 1)))
            self.count_col_width=max(widths) if widths else 1
        # root total size for bars
        self.root_total_size=None
        if root_entry is not None:
            self.root_total_size=root_entry.sum_size if root_entry.is_dir_real else root_entry.file_display_size()
    def _get_cols_order(self):
        default_order=["mark","git","size","date","permission","count","branch","name"]
        # Note: our order for date vs permission matches observed output (size, date, permission)
        raw=self.config.get('cols_order') if isinstance(self.config,dict) else None
        if isinstance(raw,list):
            cleaned=[]
            for x in raw:
                xs=str(x).lower()
                # config example uses "permission" singular, "git", "size", etc. also accept plurals?
                if xs in ("mark","git","size","permission","permissions","date","count","branch","name"):
                    cleaned.append("permission" if xs=="permissions" else xs)
            # Must be a permutation of default set - if not, fall back to default
            if set(cleaned)==set(default_order) and len(cleaned)==len(default_order):
                return cleaned
        return default_order
    def style_for(self,key,focused=True):
        return get_skin_style(self.skin,key,focused)
    def render_root_line(self,git_info_text=None,fs_info=None,for_print=False,focused=True,is_selected_root=True):
        # Returns a rendered string (with ANSI if style_enabled) WITHOUT trailing newline, truncated/padded handling will be done by caller based on for_print
        chunks=[]  # list of (text,SkinStyle)
        root=self.root_entry
        default_style=self.style_for("default",focused)
        # line base for root in print: no selected bg. In TUI selected root: selected_line bg should apply. The caller for TUI will use a generic render_line with padding handling instead of this print-specific root formatter. To unify, this function will be used for both with a parameter base_bg_style supplied by caller via attributes? We'll implement print version here and TUI version in App render code reusing build_root_chunks method below.
        chunks=self.build_root_chunks(git_info_text=git_info_text if not for_print else None,fs_info=fs_info if not for_print else None,focused=focused)
        return self.render_chunks_to_string(chunks,truncate_width=self.area_width if for_print else None,pad_to_width=None,base_style=default_style)
    def build_root_chunks(self,git_info_text=None,fs_info=None,focused=True):
        root=self.root_entry
        chunks=[]
        entry_style=entry_effective_name_style(root,self.skin,self.config,focused) if not root.is_dir_real and not root.is_symlink else get_skin_style(self.skin,"directory" if root.is_dir_real else entry_name_style_key(root),focused)
        # root is usually a directory, entry_effective would already do dir - simpler use that
        entry_style=entry_effective_name_style(root,self.skin,self.config,focused)
        if self.show_sizes_col:
            total=root.sum_size if root.is_dir_real else root.file_display_size()
            size_str=format_size(total or 0)
            # right align size to size_col_width, plus trailing space in same chunk
            text=size_str.rjust(self.size_col_width)+" "
            chunks.append((text,entry_style))
        # path chunk: root display path is absolute path string as stored (root entry path)
        path_text=root.path
        chunks.append((path_text,entry_style))
        # trailing pieces for TUI only (caller provides git_info_text / fs_info as pre-built chunk lists)
        if git_info_text:
            chunks.extend(git_info_text)
        if fs_info:
            chunks.extend(fs_info)
        return chunks
    def build_line_chunks(self,tl,selected=False,focused=True,display_object="name",opts=None):
        # returns list of (text,style) chunks for a non-root line, without line padding/truncation
        if tl.is_pruning:
            return self._build_pruning_chunks(tl,focused)
        entry=tl.entry
        chunks_by_col={}
        # mark
        if self._show_mark():
            mark_char="▶" if (selected and not False) else " "  # selected triangle only in TUI - caller for print passes selected=False for all to get space as observed
            # style for mark is default style
            chunks_by_col['mark']=[(mark_char,self.style_for("default",focused))]
        # git
        if self.show_git_col:
            git_char,git_style_key=self._git_char_and_key(entry)
            chunks_by_col['git']=[(git_char,self.style_for(git_style_key,focused))]
        # size
        if self.show_sizes_col:
            chunks_by_col['size']=self._size_chunks(entry,focused)
        # date
        if self.show_dates_col:
            date_str=format_date_for_entry(entry.deep_date if entry.deep_date is not None else entry.mtime(),self.config) if not entry.is_dir_real else format_date_for_entry(entry.deep_date if entry.deep_date is not None else entry.mtime(),self.config)
            chunks_by_col['date']=[(date_str,self.style_for("dates",focused)),(" ",self.style_for("default",focused))]
        # permission
        if self.show_perm_col:
            chunks_by_col['permission']=self._permission_chunks(entry,focused)
        # count
        if self.show_counts_col:
            cnt=entry.sum_count or 1
            cnt_str=str(cnt).rjust(self.count_col_width)
            chunks_by_col['count']=[(cnt_str,self.style_for("count",focused)),(" ",self.style_for("default",focused))]
        # device_id - not in default cols order list; if enabled, insert maybe before branch? We'll handle as a column named 'device' after count if cols order doesn't contain it - add a custom chunk list keyed 'device' and splice later
        if self.show_device_col:
            chunks_by_col['device']=[(self._device_str(entry),self.style_for("device_id_major",focused)),(" ",self.style_for("default",focused))]
        # branch
        branch_text=self._branch_text(tl)
        chunks_by_col['branch']=[(branch_text,self.style_for("tree",focused))] if branch_text else []
        # name
        chunks_by_col['name']=self._name_chunks(tl,focused,display_object)
        # Assemble in cols_order; if a requested column isn't in by_col (e.g., git column is in order but git off), skip it entirely (no spaces).
        assembled=[]
        for col in self.cols_order:
            if col in chunks_by_col:
                assembled.extend(chunks_by_col[col])
            # if device column isn't in order list but enabled, it will be omitted unless we insert it before branch as a fallback
        if self.show_device_col and 'device' not in self.cols_order:
            # insert device before branch position in assembled - approximate by placing it just before branch chunks segment
            # Find branch chunk index by style/text? Simpler append device before name chunks - we'll reconstruct: insert device chunks before last assembled segment corresponding to branch - brute: insert at position of branch in assembled based on counts: skip complexity, append before name parts:
            # We'll do a second assembly pass: rebuild with device spliced before branch col
            pass
        return assembled
    def _show_mark(self):
        v=self.config.get('show_selection_mark') if isinstance(self.config,dict) else None
        if isinstance(v,bool):
            return v
        return False
    def _git_char_and_key(self,entry):
        st=getattr(entry,'git_status',None)
        if st is None or st=="":
            return (" ","git_status_current")
        # st expected like one of 'M','N','I','C','?' mapping to keys - caller App git assigns status letter and style key tuple maybe entry.git_status could be tuple
        if isinstance(st,tuple):
            return st
        letter=str(st)[:1]
        mapping={'M':"git_status_modified",'N':"git_status_new",'I':"git_status_ignored",'C':"git_status_conflicted",'?':"git_status_new",'A':"git_status_new",'D':"git_status_other",'R':"git_status_other",'U':"git_status_conflicted"}
        return (letter,mapping.get(letter,"git_status_other"))
    def _device_str(self,entry):
        st=entry.stat_l
        if not st: return "?"
        # device id of file's device (st_dev) major/minor on linux
        try:
            major=os.major(st.st_rdev) if stat.S_ISCHR(st.st_mode) or stat.S_ISBLK(st.st_mode) else os.major(st.st_dev)
            minor=os.minor(st.st_rdev) if stat.S_ISCHR(st.st_mode) or stat.S_ISBLK(st.st_mode) else os.minor(st.st_dev)
            return f"{major}:{minor}"
        except Exception:
            return str(st.st_dev)
    def _size_chunks(self,entry,focused):
        value=entry.sum_size if entry.is_dir_real else entry.file_display_size()
        if value is None: value=0
        size_str=format_size(value).rjust(self.size_col_width)
        base_style=entry_effective_name_style(entry,self.skin,self.config,focused)
        chunks=[(size_str,base_style)]
        if self.opts.sort_mode=='size':
            # sparse char
            is_sparse=False
            if entry.is_file_like() or (entry.is_symlink and entry.stat_f and stat.S_ISREG(entry.stat_f.st_mode)):
                st=entry.stat_l
                if st and getattr(st,'st_blocks',0)*512 < st.st_size:
                    is_sparse=True
            sparse_char='s' if is_sparse else ' '
            chunks.append((sparse_char,self.style_for("sparse",focused)))
            # bar
            total=self.root_total_size or 0
            ratio=(value/total) if total else 0
            bar_text=bar_for_ratio(ratio)
            chunks.append((bar_text,base_style))
            chunks.append((" ",self.style_for("default",focused)))
        else:
            chunks.append((" ",self.style_for("default",focused)))
        return chunks
    def _permission_chunks(self,entry,focused):
        st=entry.stat_l
        if not st:
            return [("????????? ",self.style_for("default",focused))]
        mode=st.st_mode
        perms=[]
        # rwx for user group other, handling setuid/setgid/sticky - broot may show s/t or x? For now use rwx with special replacements as per unix ls logic favour s/S t/T if we want? To test reference with chmod special bits later.
        # Based on skin perm keys, each position char's style depends on its meaning: position cycles r,w,x with styles perm_r, perm_w, perm_x for present, perm__ for absent ('_').
        # If position is exec and setuid bit is set, character displayed might be 's' with perm_x style (?) We'll implement ls-like: for user exec pos, if setuid: char='s' if exec else 'S'; group setgid similar; other sticky: 't'/'T'.
        bits=[(0o400,'r'),(0o200,'w'),(0o100,'x'),(0o040,'r'),(0o020,'w'),(0o010,'x'),(0o004,'r'),(0o002,'w'),(0o001,'x')]
        perm_chars=[]
        for idx,(bit,ch) in enumerate(bits):
            present=bool(mode & bit)
            disp=ch if present else '_'
            # special bits
            if idx==2 and (mode & 0o4000):
                disp='s' if present else 'S'
            if idx==5 and (mode & 0o2000):
                disp='s' if present else 'S'
            if idx==8 and (mode & 0o1000):
                disp='t' if present else 'T'
            if disp=='_':
                style_key="perm__"
            elif ch=='r':
                style_key="perm_r"
            elif ch=='w':
                style_key="perm_w"
            else:
                style_key="perm_x"
            perm_chars.append((disp,self.style_for(style_key,focused)))
        chunks=list(perm_chars)
        # owner and group
        try:
            owner=pwd.getpwuid(st.st_uid).pw_name
        except Exception:
            owner=str(st.st_uid)
        try:
            group=grp.getgrgid(st.st_gid).gr_name
        except Exception:
            group=str(st.st_gid)
        chunks.append((f" {owner}",self.style_for("owner",focused)))
        chunks.append((f" {group}",self.style_for("group",focused)))
        chunks.append((" ",self.style_for("default",focused)))
        return chunks
    def _branch_text(self,tl):
        if tl.depth==0:
            return ""
        parts=[]
        # ancestors_last list length == depth-1, describing for depth levels 1..depth-1 if ancestor at that level was last child in its block
        for is_last_ancestor in tl.ancestors_last:
            parts.append("   " if is_last_ancestor else "│  ")
        parts.append("└──" if tl.is_last else "├──")
        return "".join(parts)
    def _build_pruning_chunks(self,tl,focused):
        # build columns for a pruning line: most columns are blank spaces with styles as per a normal line but with empty content
        chunks_by_col={}
        if self._show_mark():
