            else:
                chunks_by_col['size']=[(blank,self.style_for("default",focused)),(" ",self.style_for("default",focused))]
        if self.show_dates_col:
            # date blank width depends formatted date length - estimate based on a typical date string length 16 for default format or length of formatted current time?
            # We can compute width from format using a sample date (root mtime)
            sample=format_date_for_entry(time.time(),self.config)
            chunks_by_col['date']=[(" "*len(sample),self.style_for("default",focused)),(" ",self.style_for("default",focused))]
        if self.show_perm_col:
            # blank permission area is complex variable owner widths - approximate by a run of spaces equal to typical perm column width? In practice pruning lines rarely occur with permissions on in tests. Use spaces of length maybe the width of a normal perm line for parent entry? We'll give a chunk of spaces with length 9 + owner/group based on parent entry if available
            parent_entry=tl.parent_node.entry if tl.parent_node else None
            # Build a blank version by taking perm chunks of parent and replacing text with spaces retaining styles? Reference might produce blank spaces as one default chunk.
            chunks_by_col['permission']=[(" "*20,self.style_for("default",focused))]
        if self.show_counts_col:
            chunks_by_col['count']=[(" "*self.count_col_width,self.style_for("count",focused)),(" ",self.style_for("default",focused))]
        branch_text=self._branch_text(tl)
        chunks_by_col['branch']=[(branch_text,self.style_for("tree",focused))]
        name_text=f"{tl.pruning_count} unlisted"
        chunks_by_col['name']=[(name_text,self.style_for("pruning",focused)),(" ",self.style_for("default",focused))]
        assembled=[]
