    def _name_chunks(self,tl,focused,display_object):
        entry=tl.entry
        chunks=[]
        # Determine display string and style segments
        is_root_child=False
        # for entries included as matching in filtered mode, tl.match_indices may be set. Determine if entry is a matched entry (score not None) vs ancestor - pattern matching stored in match_info attaches to entry object via tl fields set by builder.
        has_match=tl.match_indices is not None
        # Name field string
