        is_content_match=tl.content_extract is not None
        if is_content_match:
            # Name is filename single chunk
            base_style=entry_effective_name_style(entry,self.skin,self.config,focused)
            chunks.append((entry.name,base_style))
            # link target handling for a content-matched symlink? unlikely, include link target as usual after name - content search on symlink file content might treat as file - include link chunks below generic link handling before extract
            if entry.is_symlink:
                chunks.extend(self._link_target_chunks(entry,focused))
            # trailing space chunk
            chunks.append((" ",self.style_for("default",focused)))
            # content extract chunks
            line_text,match_start,match_end=tl.content_extract
            # extract chunks: "  " (two spaces) content_extract style, then prefix text, matched text, suffix text each as chunks if non-empty
            chunks.append(("  ",self.style_for("content_extract",focused)))
            if match_start>0:
                chunks.append((line_text[:match_start],self.style_for("content_extract",focused)))
            if match_end>match_start:
                chunks.append((line_text[match_start:match_end],self.style_for("content_match",focused)))
            if match_end < len(line_text):
                chunks.append((line_text[match_end:],self.style_for("content_extract",focused)))
            return chunks
        if has_match and tl.match_indices is not None:
            # Build per-char chunks for display string
