                disp_str=os.path.relpath(entry.path,self.root_entry.path).replace(os.sep,'/') if self.root_entry else entry.name
                # parent part end index: position after last '/' in disp_str
                last_slash=disp_str.rfind('/')
                parent_end=last_slash+1 if last_slash!=-1 else 0
            else:
                disp_str=entry.name
                parent_end=0
            matched_set=set(tl.match_indices)
            base_entry_style=entry_effective_name_style(entry,self.skin,self.config,focused)
            parent_style=self.style_for("parent",focused)
            char_match_style=self.style_for("char_match",focused)
            for idx,ch in enumerate(disp_str):
                if idx < parent_end:
                    base=parent_style
                else:
                    base=base_entry_style
                if idx in matched_set:
                    # effective style: fg from char_match, bg from char_match if set else base bg, attrs union
                    eff_fg=char_match_style.fg if char_match_style.fg is not None else base.fg
                    eff_bg=char_match_style.bg if char_match_style.bg is not None else base.bg
                    eff=SkinStyle(eff_fg,eff_bg,set(base.attrs)|set(char_match_style.attrs))
                    chunks.append((ch,eff))
                else:
                    chunks.append((ch,base))
            # For directories that are matched and have children not shown? In filtered mode, no ellipsis addition (as earlier)
            # Link target for matched symlink entries: after name chunks (per char name includes only symlink name? display object path includes symlink name as last component (name) not target. Link target should follow as in unfiltered)
            if entry.is_symlink:
                chunks.extend(self._link_target_chunks(entry,focused))
            chunks.append((" ",self.style_for("default",focused)))
            return chunks
        # Unfiltered / ancestor / no match name
        # Display string is entry name (basename) even if display_object is path? In filtered mode ancestors are directories whose own line name is just their basename as a single chunk (see earlier sub directory ancestor line), not subpath. However a directory that is an ancestor but deeper than root child (e.g., a/b where a is ancestor of a matching file under b) - its line name is basename "b". Good.
        base_style=entry_effective_name_style(entry,self.skin,self.config,focused)
        chunks.append((entry.name,base_style))
        if entry.is_symlink:
            chunks.extend(self._link_target_chunks(entry,focused))
        # Ellipsis for unexpanded directories in blossom tree or flat mode
        needs_ellipsis=False
        if entry.is_dir_like():
            # Determine if this line's node is unexpanded / flat / max depth etc - caller sets a flag on tl via attributes? We can determine from tl.node state if present and state == 'unexpanded' and has children
            if tl.node is not None:
                if tl.node.state=='unexpanded':
                    # check has children (children_entries may be loaded)
                    if tl.node.children_entries:
                        needs_ellipsis=True
                    else:
                        # has_children check may require loading, but node state unexpanded in blossom implies we loaded candidates etc and know it has children because it was candidate - but some leaf empty directories are treated as ... node.state for a directory with no visible children but filesystem children hidden by filters would be in children_entries empty - then no ellipsis
                        needs_ellipsis=False
            else:
                # flat lines tl.node is None: ellipsis if entry is a directory with any visible children (or any filesystem children? Use visible children count via checking children list computed for flat - we can use node_has_children with a temporary node - cache)
                # For speed, we can try list visible children for this entry using a temporary BlossomNode and the current opts/ignorer stored on renderer? Renderer doesn't hold ignorer/opts for this check properly (opts available). We'll attempt a cheap scandir any entry check respecting hidden/ignore? For ellipsis in flat sort, a dir with only hidden files and hidden off - does it show … ? Likely based on visible children under current filters (search/load children during flat building discarded). To know, flat builder could set a flag attribute on entry object (has_visible_children) - we will set entry._has_children_for_ellipsis in builders
                needs_ellipsis=bool(getattr(entry,'_flat_has_children',False))
        if needs_ellipsis:
            chunks.append((" …",base_style))
        chunks.append((" ",self.style_for("default",focused)))
        return chunks
    def _link_target_chunks(self,entry,focused):
        chunks=[]
        link_style=self.style_for("link",focused)
        chunks.append((" -> ",link_style))
        target_path=entry.link_target or ""
        if entry.is_broken_link:
            target_style=self.style_for("file_error",focused)
        else:
            # create a temporary FSEntry for target to determine style
            try:
                t_entry=FSEntry(target_path)
                # For target style, use effective name style of target entry (directory/file/exe) - but with target entry's symlink status false
                target_style=entry_effective_name_style(t_entry,self.skin,self.config,focused)
            except Exception:
                target_style=self.style_for("file",focused)
        chunks.append((target_path,target_style))
        return chunks
    def render_chunks_to_string(self,chunks,truncate_width=None,pad_to_width=None,base_style=None,focused=True,selected=False):
        # chunks are (text,SkinStyle) with possible None fg/bg to inherit from base_style (default/selected)
        # Returns string with ANSI codes (if style_enabled), truncated to truncate_width visible, padded if pad_to_width
        # For TUI padding, caller should handle padding truncation separately with a fill chunk - this function can pad with spaces using base_style.
        out_pieces=[]
        vis_used=0
        # Predetermine base bg/fg for inheritance: base_style currently is default style (skin default) for print, or for TUI selected line caller may pass a merged base (fg default fg, bg selected bg) as base_style
        for text,style in chunks:
            if truncate_width is not None and vis_used>=truncate_width:
                break
            piece_text=text
            piece_vis=text_width(piece_text)
            if truncate_width is not None and vis_used+piece_vis>truncate_width:
                # truncate piece_text by visible width
                allowed=truncate_width-vis_used
                truncated=""; w=0
                for ch in piece_text:
                    cw=text_width(ch)
                    if w+cw>allowed: break
                    truncated+=ch; w+=cw
                piece_text=truncated; piece_vis=w
            if piece_text=="" and not style.attrs and style.fg is None and style.bg is None:
                # empty plain chunk renders nothing
                vis_used+=piece_vis
                continue
            # effective style
            eff=merge_bg_fg(style,base_style) if base_style else style
            out_pieces.append(render_styled_chunk(piece_text,eff,self.style_enabled,self.true_colors))
            vis_used+=piece_vis
        result="".join(out_pieces)
        if pad_to_width is not None and vis_used < pad_to_width:
            pad_len=pad_to_width-vis_used
            pad_text=" "*pad_len
            pad_style=base_style if base_style else self.style_for("default",focused)
            result+=render_styled_chunk(pad_text,pad_style,self.style_enabled,self.true_colors)
            vis_used+=pad_len
        # final bg reset for print lines: In reference print_tree lines end with \x1b[49m if styles are enabled (even if chunk bg was none, as final reset for line's background).
        # Caller should append that separately if needed for print mode - not in TUI rendering where cursor/EOL background handling differs. We'll not add here.
        return result

