def make_line_renderer(app,panel,for_print=False):
    opts=panel.opts or app.opts
    # Determine style enabled for print vs TUI
    if for_print:
        if opts.color=="yes":
            style_enabled=True
        elif opts.color=="auto":
            # stdout is tty?
            try: style_enabled=os.isatty(1)
            except Exception: style_enabled=False
        else:
            style_enabled=False
    else:
        style_enabled=app.style_enabled
    renderer=LineRenderer(opts,app.config,app.skin,style_enabled,app.area_width,panel.root_entry,panel.lines)
    renderer.style_enabled=style_enabled
    return renderer

def render_print_tree(app,panel):
    renderer=make_line_renderer(app,panel,for_print=True)
    default_style=renderer.style_for("default",True)
    out_bytes=[]
    # limit lines to height-1 if needed
    limit=max(1,app.area_height-1) if app.area_height else len(panel.lines)
    lines_to_print=panel.lines[:limit]
    for idx,tl in enumerate(lines_to_print):
        if tl.depth==0:
            chunks=renderer.build_root_chunks(focused=True)
            line_str=renderer.render_chunks_to_string(chunks,truncate_width=app.area_width,pad_to_width=None,base_style=default_style)
        else:
            display_obj=primary_display_object(panel.pattern_ast) if panel.pattern_ast else "name"
            if tl.is_pruning:
                chunks=renderer._build_pruning_chunks(tl,True)
            else:
                chunks=renderer.build_line_chunks(tl,selected=False,focused=True,display_object=display_obj)
            line_str=renderer.render_chunks_to_string(chunks,truncate_width=app.area_width,pad_to_width=None,base_style=default_style)
        if renderer.style_enabled:
            line_str+=esc_seq("\x1b[49m")
        out_bytes.append(line_str.encode('utf-8'))
    data=b"\r\n".join(out_bytes)
    if out_bytes:
