        # Instead our history model: There is a snapshot taken when pattern session started (pushed at that time in set_pattern function). Clearing pattern via escape should NOT pop it yet? Let's implement escape as do_back but with selection preservation and special handling to keep original initial snapshot below a new cleared state.
        # Approach: If history stack has a snapshot for before-pattern, pop it and restore but preserve selection, and then push ... hmm
        # Implement as: clear filter as a new state, retaining snapshot stack as it was at start of pattern session (so next back will go to before-pattern snapshot, whose selection is original).
        # Our push_history at pattern start pushed snapshot S0. In current filtered state, stack top is S0 if no other pushes. Escape clear should create new current state C (cleared, selection preserved) while stack remains [S0] - then next Escape (input empty) will do_back popping S0 restoring its selection root - matches observed second escape.
        # So simply: clear input/pattern, rebuild, do not pop/push history.
        sel=selected_entry(panel)
        panel.pattern_str=""; panel.input_text=""; panel.input_cursor=0
        panel._desired_selection_path=sel.path if sel else None
        panel_build_tree(app,panel)
        return True
    # Input empty: go back
    return do_back(app,panel)

def do_back(app,panel):
    if not hasattr(panel,'_history') or not panel._history:
        # If quit_on_last_cancel config true, quit
        if app.config.get('quit_on_last_cancel') is True:
            app.should_quit=True; return True
        # No history - if panel is a secondary panel, close it?
        if len(app.panels)>1 and panel.type!='tree':
            close_current_panel(app)
            return True
        return True
    snap=panel._history.pop()
    # When going back from a focused state to a state with a pattern, restore exactly as snapshot (input, root, selection)
    # Preserve selection? In observed focus back case, selection in snapshot was sub1 which matched preserve logic anyway. In cases where clear filter state is current and we pop to before-pattern, selection in snapshot is root which is desired for second esc case. So do NOT preserve current selection when popping via back - restore snapshot as is.
    restore_snapshot(app,panel,snap,preserve_selection_path=snap.get('selected_path'))
    return True

def handle_selection_movement(app,panel,name,raw_args):
    if panel.type=="help":
        # help panel scrolling handled as selection / scroll
        handle_help_movement(app,panel,name,raw_args)
        return True
    if panel.type=="preview":
        handle_preview_movement(app,panel,name,raw_args)
        return True
    # Tree/fs/stage lines list movement
    lines=panel.lines
    if not lines:
        return True
    count=1
    if raw_args:
        try: count=int(raw_args.strip().split()[0])
        except Exception: count=1
    idx=panel.selected_index
    page_size=max(1,app.area_height-2)
    def set_idx(new_idx):
        panel.selected_index=max(0,min(new_idx,len(lines)-1))
        sel=selected_entry(panel)
        panel._last_selected_path=sel.path if sel else None
    if name=="line_down":
        set_idx(idx+count if idx+count < len(lines) else 0 if (idx+count>=len(lines)) else idx+count)
        # cycling: if move beyond last, wrap to first (0)
        if idx+count>=len(lines):
            # The above set_idx clamped/wrapped incorrectly due expression - redo:
            panel.selected_index=(idx+count)%len(lines)
    elif name=="line_down_no_cycle":
        set_idx(min(idx+count,len(lines)-1))
    elif name=="line_up":
        # wrap to last
        panel.selected_index=(idx-count)%len(lines)
    elif name=="line_up_no_cycle":
        set_idx(max(idx-count,0))
    elif name=="page_down":
        set_idx(min(idx+page_size,len(lines)-1))
    elif name=="page_up":
        set_idx(max(idx-page_size,0))
    elif name=="select_first":
        set_idx(0)
    elif name=="select_last":
        set_idx(len(lines)-1)
    elif name=="next_dir" or name=="previous_dir":
        direction=1 if name=="next_dir" else -1
        j=idx+direction
        while 0<=j<len(lines):
            e=lines[j].entry
            if e and e.is_dir_like():
                set_idx(j); break
            j+=direction
    elif name=="next_same_depth" or name=="previous_same_depth":
        direction=1 if name.startswith("next") else -1
        depth=lines[idx].depth if lines else 0
        j=idx+direction
        while 0<=j<len(lines):
            if lines[j].depth==depth and not lines[j].is_pruning:
                set_idx(j); break
            j+=direction
    elif name=="next_match":
        # In input context with completions, next_match is Tab - if there's a verb completion active, handle in input handler rather than here. As an internal execution via cmd, it selects next matching entry (cycling)
        matches=[i for i,tl in enumerate(lines) if tl.entry and panel._match_info and tl.entry.path in panel._match_info]
        if matches:
            # find next after current
            for m in matches:
                if m>idx:
                    set_idx(m); return True
            set_idx(matches[0])
        else:
            set_idx(idx+1 if idx+1<len(lines) else 0)
    elif name=="previous_match":
        matches=[i for i,tl in enumerate(lines) if tl.entry and getattr(panel,'_match_info',None) and tl.entry.path in panel._match_info]
        if matches:
            for m in reversed(matches):
                if m<idx:
                    set_idx(m); return True
            set_idx(matches[-1])
    # remember last selected
    sel=selected_entry(panel)
    if sel: panel._last_selected_path=sel.path
    return True

def handle_toggle_sort(app,panel,name,raw_args):
