def is_image_file(path):
    ext=Path(path).suffix.lower().lstrip('.')
    return ext in ("png","jpg","jpeg","gif","bmp","webp","svg","ico","tiff","avif")

def apply_preview_transformer(app,entry,data_bytes,mode):
    transformers=app.config.get('preview_transformers') if isinstance(app.config,dict) else None
    if not isinstance(transformers,list):
        return None
    ext=entry.extension().lower()
    for tr in transformers:
        if not isinstance(tr,dict): continue
        # Normalize keys
        d={normalize_key(str(k)):v for k,v in tr.items()}
        inputs=d.get('input_extensions') or []
        if not isinstance(inputs,list): continue
        if ext not in [str(x).lower().lstrip('.') for x in inputs]:
            continue
        command=d.get('command')
        if not command: continue
        out_mode=str(d.get('mode','text')).lower()
        # Determine placeholders handling: command may be list with "{input-path}" etc. If placeholders present, create temp files for input/output as documented.
        import tempfile
        try:
            if isinstance(command,list):
                # check for placeholders in any element
                has_input_path=any("{input-path}" in str(c) for c in command)
                has_output_path=any("{output-path}" in str(c) for c in command) or any("{output-dir}" in str(c) for c in command)
                if has_input_path or has_output_path:
                    with tempfile.TemporaryDirectory() as td:
                        input_path=entry.path
                        output_ext=str(d.get('output_extension') or "txt")
                        output_path=os.path.join(td,"output."+output_ext)
                        output_dir=td
                        argv=[]
                        for part in command:
                            s=str(part).replace("{input-path}",input_path).replace("{output-path}",output_path).replace("{output-dir}",output_dir)
                            argv.append(s)
                        result=subprocess.run(argv,capture_output=True,timeout=10)
                        if os.path.exists(output_path):
                            content=Path(output_path).read_bytes()
                            return (out_mode,content)
                        else:
                            # find any file in output dir
                            files=[p for p in Path(td).rglob("*") if p.is_file()]
                            if files:
                                return (out_mode,files[0].read_bytes())
                            return (out_mode,result.stdout)
                else:
                    result=subprocess.run([str(c) for c in command],input=data_bytes,capture_output=True,timeout=10)
                    return (out_mode,result.stdout)
            elif isinstance(command,str):
                result=subprocess.run(command,input=data_bytes,capture_output=True,shell=True,timeout=10,executable=os.environ.get("SHELL","/bin/sh"))
                return (out_mode,result.stdout)
        except Exception:
            return None
    return None

