def open_file_os(app,panel,entry,leave=False):
    # Execute default opener for file/directory.
    # Approach:
    # - If entry is a text file and a user verb bound to Enter key with extensions etc would have been handled as a verb dispatch before this fallback (in Enter handling). This fallback is the internal open_stay for files.
    # - Broot uses `open` crate to open file with system default application. On Linux that uses xdg-open. Implement: try run xdg-open path as external command (suspend terminal if in TUI). If xdg-open not available, do nothing / status error.
    # External runner hook will be set by App main loop (app._run_external_argv)
    runner=getattr(app,'_run_external_argv',None)
    opener=None
