# ---------------- Terminal & rendering ----------------

class Terminal:
    def __init__(self,app):
        self.app=app
        self.input_fd=None
        self.output_fd=2  # stderr
        self.old_attr=None
        self.entered=False
        self.input_is_devtty=False
    def acquire_input(self):
        # try stdin as tty, else /dev/tty
        try:
            if os.isatty(0):
                self.input_fd=0; return True
        except Exception:
            pass
        try:
            fd=os.open("/dev/tty",os.O_RDONLY)
            self.input_fd=fd; self.input_is_devtty=True; return True
        except OSError as e:
            # Simulate termimad error after alt screen sequence
            err_no=e.errno or 6
            msg=os.strerror(err_no)
            # Write alt screen and leave sequences to stderr
            enter_seq=b"\x1b[?1049h\x1b[?25l\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1015h\x1b[?1006h"
            leave_seq=b"\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l\x1b[?25h\x1b[?1049l"
            try:
                os.write(2,enter_seq+leave_seq)
            except OSError:
                pass
            raise BroootError(f"Termimad Error : IO error: {msg} (os error {err_no})\n")
    def enter(self):
        self.acquire_input()
        try:
            self.old_attr=termios.tcgetattr(self.input_fd)
        except Exception:
            self.old_attr=None
        # Write alt screen sequence to stderr
        seq=b"\x1b[?1049h\x1b[?25l"
