def panel_layout(app):
    total_w=app.area_width; total_h=app.area_height
    n=len(app.panels)
    if n<=1:
        return [(0,0,total_w,total_h)] if n==1 else []
    # compute widths
    # overrides
    overrides=getattr(app,'_panel_width_overrides',{})
    deltas=getattr(app,'_divider_deltas',{})
    widths=[total_w//n]*n
    for i in range(total_w % n):
        widths[i]+=0  # panels may get remainder allocated to last? We'll give remainder to last panel
    widths[-1]+= total_w - sum(widths)
    # apply explicit widths in order
    for idx,w in overrides.items():
        if 0<=idx<n:
            # adjust by taking/giving from last panel rent-free-ish - simple: set width, then adjust last panel to keep sum
            diff=w-widths[idx]
            widths[idx]=w
            widths[-1]-=diff
    # apply divider deltas
    for idx,dx in deltas.items():
        if 0<=idx<n-1:
            widths[idx]+=dx; widths[idx+1]-=dx
    # clamp minimum 5 each and rescale? if any negative, set to 5 and adjust last
    rects=[]; x=0
    for i,w in enumerate(widths):
        w=max(5,w)
        if i==n-1:
            w=total_w-x
        rects.append((x,0,w,total_h)); x+=w
    return rects

