    old=renderer.style_enabled; renderer.style_enabled=style_enabled
    s=renderer.render_chunks_to_string(chunks,truncate_width=width,pad_to_width=width,base_style=base_style)
    renderer.style_enabled=old
    return s

def build_root_extra_chunks(app,panel,renderer):
    extra=[]
