    pct=int(math.floor(used/total*100+0.5)) if total else 0
    # bar - determine good_to_bad style key based on pct bucket: 0-9 scale mapping percent to index 0..9 (0 best, 9 worst)
    idx=min(9,max(0,int(pct//10))) if pct<100 else 9
    bar_style_key=f"good_to_bad_{idx}"
    bar_style=renderer.style_for(bar_style_key,True)
    used_str=format_size(used); total_str=format_size(total)
    occupation_ratio=used/total if total else 0
    bar_text=bar_for_ratio(occupation_ratio)  # width10
    # Format observed: "<dev> <used>/<total> <bar> <pct>%"
    chunks=[]
    chunks.append((dev_name,renderer.style_for("default",True)))
    chunks.append((" ",renderer.style_for("default",True)))
    chunks.append((used_str,bar_style))
    chunks.append((f"/{total_str}",renderer.style_for("default",True)))
    chunks.append((" ",renderer.style_for("default",True)))
    # bar chunk style: In TUI root fs bar, bar graph is rendered as background ? Existing captures showed bar chars as blocks with a background color of good_to_bad - our bar_style as fg of blocks might be wrong side. Use bar_style but swap fg<>bg if style had only fg colour defined: bar blocks are foreground chars themselves forming bar, colour is their fg. In fs panel screenshots, bar is a horizontal bar made of coloured background spaces maybe. For root line, observed tmux capture: after total, segments: ` ██▏       ` where blocks are ? tmux capture normalized - cannot tell fg vs bg from plain. From raw stderr earlier for space? we'll use fg bar_style.
    chunks.append((bar_text,bar_style))
    chunks.append((f" {pct}%",bar_style))
    return chunks

def get_git_branch_info(path):
    # Use git command if available for branch and diff stats
    repo_root=get_git_root_for_path(path)
    if not repo_root:
        return None
    branch=""
    try:
        head_path=None
        git_path=Path(repo_root)/".git"
        if git_path.is_dir():
            head_path=git_path/"HEAD"
        elif git_path.is_file():
            txt=git_path.read_text(errors='ignore')
            m=re.search(r'gitdir:\s*([^\n]+)',txt)
            if m:
                gd=Path(m.group(1).strip())
                if not gd.is_absolute(): gd=Path(os.path.normpath(str(Path(repo_root)/gd)))
                head_path=gd/"HEAD"
        if head_path and head_path.exists():
            head=head_path.read_text(errors='ignore').strip()
            if head.startswith("ref:"):
                branch=head[4:].strip().split('/')[-1] if '/' in head[4:].strip() else head[4:].strip()
                # ref is refs/heads/master - branch name maybe full after heads/
                ref=head[4:].strip()
                if ref.startswith("refs/heads/"):
                    branch=ref[len("refs/heads/"):]
            else:
                branch=head[:7]
    except Exception:
        pass
    insertions=0; deletions=0
    # Subprocess git diff for stats if git available
    try:
        import shutil
        if shutil.which("git"):
            r=subprocess.run(["git","-C",repo_root,"diff","--numstat","HEAD"],capture_output=True,text=True,timeout=3)
            if r.returncode==0:
                for line in r.stdout.splitlines():
                    parts=line.split()
                    if len(parts)>=2:
                        try:
                            insertions+=int(parts[0]) if parts[0]!="-" else 0
                            deletions+=int(parts[1]) if parts[1]!="-" else 0
                        except Exception:
                            pass
    except Exception:
        pass
    return (branch,insertions,deletions)

