# ---------------- Remote socket ----------------

def broot_socket_path(name):
    if name is None:
        return None
    # If name appears to be a path (contains '/'), use it as a filesystem path directly (expand ~)
    if '/' in name:
        return expand_tilde_path(name)
    # temp dir: use tempfile.gettempdir() which respects TMPDIR env (std::env::temp_dir logic)
    import tempfile
    td=tempfile.gettempdir()
    return os.path.join(td,f"broot-server-{name}.sock")

