        if not os.path.exists(target):
            raise BroootError(io_error_msg(FileNotFoundError(errno.ENOENT,os.strerror(errno.ENOENT))))
    sock=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM)
    try:
        sock.connect(path)
    except OSError as e:
        err_no=e.errno or 2
        raise BroootError(f"error on the socket: {os.strerror(err_no)} (os error {err_no})\n")
    try:
        if msg_type=="GET_ROOT":
            sock.sendall(b"GET_ROOT\n")
            # shutdown write? Reference client likely reads response until server closes connection. Keep write open while reading - server responds after reading a line and closes its side.
            data=b""
            sock.settimeout(5)
            while True:
                try:
                    chunk=sock.recv(4096)
                except OSError:
                    break
                if not chunk:
