            if not hasattr(self.app,'_remote_queue'):
                self.app._remote_queue=[]
            self.app._remote_queue.append(('CMD',cmd_line))
            return
        # unknown header ignore
        return
    def close(self):
        self.stop=True
        try:
            if self.sock: self.sock.close()
        except Exception: pass
        try:
            if self.path and os.path.lexists(self.path): os.unlink(self.path)
        except OSError: pass

