def preview_line_matches(ast,line):
    if ast is None: return True
    # Use evaluate_pattern logic by creating a fake entry-like object
    class Fake:
        pass
    # Simplify: convert pattern to plain fuzzy matching on line text using elementary evaluator by fabricating an entry whose name is line text - not ideal for content patterns.
    # Use a recursive function matching AST against line string using elementary kinds (fuzzy/exact/regex/tokens on line as candidate string)
    def eval_node(node):
        if node[0]=='elem':
            elem=node[1]
            body=elem.body
            if elem.kind=="fuzzy":
                return fuzzy_best_alignment(normalize_for_fuzzy(body),normalize_for_fuzzy(line),line) is not None
            if elem.kind=="exact":
                return body in line
            if elem.kind=="regex":
                return elem.regex_obj.search(line) is not None if elem.regex_obj else False
            if elem.kind=="tokens":
                cand=normalize_for_fuzzy(line)
                return all(normalize_for_fuzzy(t) in cand for t in elem.tokens)
            return False
        if node[0]=='not':
            return not eval_node(node[1])
        if node[0]=='and':
            return eval_node(node[1]) and eval_node(node[2])
        if node[0]=='or':
            return eval_node(node[1]) or eval_node(node[2])
        return False
    try:
        return eval_node(ast)
    except Exception:
        return False

