import pathlib
p=pathlib.Path("broot.py"); t=p.read_text()
helpers=r'''
def build_root_extra_chunks(app,panel,renderer):
    extra=[]
    opts=panel.opts or app.opts
    root_path=panel.root_path
    if opts.show_git_info or opts.git_status_only:
        git_info=get_git_branch_info(root_path)
        if git_info:
            branch,ins,dele=git_info
            extra.append((" \u169c ",renderer.style_for("git_branch",True)))
            extra.append((branch,renderer.style_for("git_branch",True)))
            if ins or dele:
                extra.append((" ",renderer.style_for("default",True)))
                if ins:
                    extra.append((f"+{ins}",renderer.style_for("git_insertions",True)))
                if dele:
                    extra.append((f"-{dele}",renderer.style_for("git_deletions",True)))
    if opts.show_root_fs:
        fs_chunks=build_fs_info_chunks(app,renderer,root_path)
        if fs_chunks:
            extra.append(("  ",renderer.style_for("default",True)))
            extra.extend(fs_chunks)
    return extra

def build_fs_info_chunks(app,renderer,path):
    try:
        import shutil
        total,used,free=shutil.disk_usage(path)
    except Exception:
        return []
    dev_name="?"
    try:
        best=""
        with open("/proc/mounts") as f:
            for line in f:
                parts=line.split()
                if len(parts)>=2:
                    mp=parts[1].replace("\\040"," ")
                    if os.path.abspath(path)==mp or os.path.abspath(path).startswith(mp.rstrip("/")+"/") or mp=="/":
                        if len(mp)>=len(best):
                            best=mp; dev_name=parts[0]
    except Exception:
        pass
    pct=int(math.floor(used/total*100+0.5)) if total else 0
    idx=min(9,max(0,int(pct//10))) if pct<100 else 9
    bar_style_key=f"good_to_bad_{idx}"
    bar_style=renderer.style_for(bar_style_key,True)
    used_str=format_size(used); total_str=format_size(total)
    occupation_ratio=used/total if total else 0
    bar_text=bar_for_ratio(occupation_ratio,bar_width=9)
    chunks=[]
    chunks.append((dev_name,renderer.style_for("default",True)))
    chunks.append((" ",renderer.style_for("default",True)))
    chunks.append((used_str,bar_style))
    chunks.append((f"/{total_str}",renderer.style_for("default",True)))
    chunks.append((" ",renderer.style_for("default",True)))
    # Bar in references uses background+characters - approximate by using bar_style as fg for blocks (our bar_text)
    # Later refinement may adapt style. Keep bar_style as fg for char portion.
    chunks.append((bar_text,bar_style))
    chunks.append((f" {pct}%",bar_style))
